// src/pages/users/ListUsersPage.tsx
import {
  Box,
  Heading,
  HStack,
  Button,
  Input,
  Icon,
  chakra,
} from "@chakra-ui/react";
import {
  FaPlus,
  FaTrash,
  FaUpload,
  FaPrint,
  FaDownload,
  FaFilter,
  FaEdit,
  FaSearch,
} from "react-icons/fa";
import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import SidebarLayout from "../../components/ui/SidebarLayout";

type Pessoa = {
  id: number;
  nome: string;
  matricula: string;
  rg: string;
  cpf: string;
  telefone: string;
  cargo: string;
  ativo: boolean;
  listaExcecao: boolean;
  administrador: boolean;
  email: string;
};

export default function ListUsersPage() {
  const navigate = useNavigate();
  const [pessoas, setPessoas] = useState<Pessoa[]>([]);
  const [selecionados, setSelecionados] = useState<number[]>([]);
  const [showFiltro, setShowFiltro] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    axios
      .get("http://localhost:3000/pessoas")
      .then((res) => setPessoas(res.data))
      .catch(() =>
        alert("Erro ao carregar pessoas")
      );
  }, [alert]);

  const toggleSelecionado = (id: number) => {
    setSelecionados((prev) =>
      prev.includes(id) ? prev.filter((pid) => pid !== id) : [...prev, id]
    );
  };

  const toggleSelecionarTodos = () => {
    if (selecionados.length === pessoas.length) {
      setSelecionados([]);
    } else {
      setSelecionados(pessoas.map((p) => p.id));
    }
  };

  const removerSelecionados = async () => {
    try {
      for (const id of selecionados) {
        await axios.delete(`http://localhost:3000/pessoas/${id}/1`);
      }

      setPessoas((prev) => prev.filter((p) => !selecionados.includes(p.id)));
      setSelecionados([]);
      alert("Pessoas removidas com sucesso");
    } catch (err) {
      console.error(err);
      alert({
        title: "Erro ao remover pessoas",
        status: "error",
        isClosable: true,
      });
    }
  };


  const removerPessoa = async (id: number) => {
    try {
      await axios.delete(`http://localhost:3000/pessoas/${id}/1`);
      setPessoas((prev) => prev.filter((p) => p.id !== id));
      alert("Pessoa excluída com sucesso");
    } catch (err) {
      console.error(err);
      alert("Erro ao excluir pessoa");
    }
  };

  // Filtra a lista de pessoas conforme o termo de busca
  const pessoasFiltradas = pessoas.filter((p) =>
    p.nome.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <SidebarLayout>
      <Box bg="dark.soft" minH="100vh" px={6} py={8}>
        <Box maxW="1200px" mx="auto">
          <Heading size="lg" mb={6} color="brand.500">
            Cadastro de Pessoas
          </Heading>

          {/* === Barra superior de botões e pesquisa === */}
          <HStack justify="space-between" mb={4} wrap="wrap" gap={4}>
            <HStack gap={3}>
              <Button
                colorScheme="brand"
                onClick={() => navigate("/add-user")}
                _hover={{ bg: "brand.600" }}
              >
                <Icon as={FaPlus} mr={2} /> Adicionar
              </Button>
              <Button
                colorScheme="red"
                onClick={removerSelecionados}
                disabled={selecionados.length === 0}
                _disabled={{ opacity: 0.6, cursor: "not-allowed" }}
              >
                <Icon as={FaTrash} mr={2} /> Remover{" "}
                {selecionados.length > 0 && `(${selecionados.length})`}
              </Button>
              <Button
                variant="outline"
                colorScheme="brand"
                onClick={() => setShowFiltro((v) => !v)}
                _hover={{ bg: "brand.50" }}
              >
                <Icon as={FaFilter} mr={2} />
                {showFiltro ? "Ocultar Filtro" : "Filtrar"}
              </Button>
            </HStack>

            <HStack gap={3}>
              <Button colorScheme="brand" _hover={{ bg: "brand.600" }}>
                <Icon as={FaUpload} mr={2} /> Importar
              </Button>
              <Button colorScheme="brand" _hover={{ bg: "brand.600" }}>
                <Icon as={FaPrint} mr={2} /> Imprimir
              </Button>
              <Button colorScheme="brand" _hover={{ bg: "brand.600" }}>
                <Icon as={FaDownload} mr={2} /> Exportar CSV
              </Button>
            </HStack>
          </HStack>

          {/* === Caixa de busca sempre visível === */}
          <HStack gap={2} mb={4} maxW="400px">
            <Icon as={FaSearch} color="gray.300" />
            <Input
              placeholder="Pesquisar por nome..."
              bg="gray.50"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              _placeholder={{ color: "gray.400" }}
            />
          </HStack>

          {/* === Filtro avançado (opcional) === */}
          {showFiltro && (
            <Box bg="white" p={4} mb={4} borderRadius="md" boxShadow="sm">
              <HStack gap={3} wrap="wrap">
                <Input
                  placeholder="Filtrar por matrícula"
                  bg="gray.50"
                  size="sm"
                  maxW="200px"
                />
                <Input
                  placeholder="Filtrar por e-mail"
                  bg="gray.50"
                  size="sm"
                  maxW="250px"
                />
                {/* Aqui você pode adicionar outros campos de filtro */}
                <Button colorScheme="brand" size="sm">
                  Aplicar Filtro
                </Button>
              </HStack>
            </Box>
          )}

          {/* === Tabela de usuários com zebra stripes === */}
          <Box overflowX="auto" bg="white" borderRadius="md" boxShadow="base">
            <chakra.table width="100%">
              <chakra.thead bg="gray.800">
                <chakra.tr>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    <chakra.input
                      type="checkbox"
                      checked={
                        selecionados.length === pessoas.length && pessoas.length > 0
                      }
                      onChange={toggleSelecionarTodos}
                    />
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    Id
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="left"
                    color="white"
                    fontSize="sm"
                  >
                    Nome
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    Matrícula
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    RG
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    CPF
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    Telefone
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    Cargo
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    Ativo
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    Lista Exceção
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    Administrador
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    Ações
                  </chakra.th>
                </chakra.tr>
              </chakra.thead>
              <chakra.tbody>
                {pessoasFiltradas.map((pessoa) => (
                  <chakra.tr
                    key={pessoa.id}
                    _odd={{ bg: "gray.50" }}
                  >
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                    >
                      <chakra.input
                        type="checkbox"
                        checked={selecionados.includes(pessoa.id)}
                        onChange={() => toggleSelecionado(pessoa.id)}
                      />
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {pessoa.id}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="left"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {pessoa.nome}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {pessoa.matricula}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {pessoa.rg}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {pessoa.cpf}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {pessoa.telefone}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {pessoa.cargo}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {pessoa.ativo ? "Sim" : "Não"}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {pessoa.listaExcecao ? "Sim" : "Não"}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {pessoa.administrador ? "Sim" : "Não"}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                    >
                      <HStack justify="center" gap={2}>
                        <Button
                          size="xs"
                          colorScheme="blue"
                          onClick={() => navigate(`/edit-user/${pessoa.id}`)}
                          _hover={{ bg: "blue.600" }}
                        >
                          <Icon as={FaEdit} mr={1} /> Editar
                        </Button>
                        <Button
                          size="xs"
                          colorScheme="red"
                          onClick={() => removerPessoa(pessoa.id)}
                          _hover={{ bg: "red.600" }}
                        >
                          <Icon as={FaTrash} mr={1} /> Excluir
                        </Button>
                      </HStack>
                    </chakra.td>
                  </chakra.tr>
                ))}
              </chakra.tbody>
            </chakra.table>
          </Box>
        </Box>
      </Box>
    </SidebarLayout>
  );
}
