// src/pages/users/UsersCreditsPage.tsx
import {
    Box,
    Heading,
    HStack,
    VStack,
    Input,
    Button,
    Icon,
    Text,
    Spinner,
} from "@chakra-ui/react";
import { useToast } from "@chakra-ui/toast";
import { FaArrowCircleLeft, FaPlus } from "react-icons/fa";
import { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import axios from "axios";
import SidebarLayout from "../../components/ui/SidebarLayout";

export default function UsersCreditsPage() {
    const toast = useToast();
    const navigate = useNavigate();
    const { id } = useParams<{ id: string }>(); // id do usuário
    const [loading, setLoading] = useState(true);
    const [creditos, setCreditos] = useState<number>(0);
    const [novoCredito, setNovoCredito] = useState<number>(0);

    // Carrega créditos atuais do usuário
    useEffect(() => {
        if (!id) return;
        axios
            .get<{ creditos: number }>(`http://localhost:3000/pessoas/${id}/creditos`)
            .then((res) => {
                setCreditos(res.data.creditos);
            })
            .catch(() => {
                toast({
                    title: "Erro ao carregar créditos",
                    status: "error",
                    isClosable: true,
                });
                navigate("/list-users");
            })
            .finally(() => setLoading(false));
    }, [id, navigate, toast]);

    if (loading) {
        return (
            <SidebarLayout>
                <Box bg="dark.soft" minH="100vh" px={6} py={8}>
                    <Spinner size="xl" color="brand.500" />
                </Box>
            </SidebarLayout>
        );
    }

    const handleAdicionar = async () => {
        try {
            await axios.post(`http://localhost:3000/pessoas/${id}/creditos`, {
                delta: novoCredito,
            });
            setCreditos((prev) => prev + novoCredito);
            setNovoCredito(0);
            toast({
                title: "Créditos atualizados",
                status: "success",
                isClosable: true,
            });
        } catch {
            toast({
                title: "Erro ao atualizar créditos",
                status: "error",
                isClosable: true,
            });
        }
    };

    return (
        <SidebarLayout>
            <Box bg="dark.soft" minH="100vh" px={6} py={8}>
                <Box maxW="600px" mx="auto">
                    <HStack mb={4} gap={2}>
                        <Icon as={FaArrowCircleLeft} />
                        <Button
                            as={FaArrowCircleLeft}
                            onClick={() => navigate("/list-users")}
                            colorScheme="gray"
                            size="sm"
                        >
                            Voltar
                        </Button>
                        <Heading size="lg" color="brand.500">
                            Créditos do Usuário #{id}
                        </Heading>
                    </HStack>

                    <Box bg="white" p={6} borderRadius="md" boxShadow="md">
                        <VStack gap={6} align="stretch">
                            <HStack justify="space-between">
                                <Text fontSize="md" fontWeight="medium">
                                    Créditos Atuais:
                                </Text>
                                <Text fontSize="xl" fontWeight="bold" color="brand.500">
                                    {creditos}
                                </Text>
                            </HStack>

                            <HStack gap={3}>
                                <Input
                                    type="number"
                                    placeholder="Valor a adicionar/subtrair"
                                    value={novoCredito}
                                    onChange={(e) => setNovoCredito(Number(e.target.value))}
                                    bg="gray.50"
                                    size="md"
                                />
                                <Icon as={FaPlus} />
                                <Button
                                    as={FaPlus}
                                    colorScheme="brand"
                                    onClick={handleAdicionar}
                                >
                                    Atualizar
                                </Button>
                            </HStack>
                        </VStack>
                    </Box>
                </Box>
            </Box>
        </SidebarLayout>
    );
}
