// src/pages/terminals/AddTerminalPage.tsx
import React, { useState } from "react";
import {
  Box, Heading, HStack, VStack, Input, Button, Icon, Text, chakra,
} from "@chakra-ui/react";
import { FaArrowCircleLeft, FaSave } from "react-icons/fa";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import SidebarLayout from "../../components/ui/SidebarLayout";

type Form = { name: string; host: string; port: number; model: string };

export default function AddTerminalPage() {
  const [form, setForm] = useState<Form>({ name: "", host: "", port: 80, model: "" });
  const nav = useNavigate();

  const onChange = (e: React.ChangeEvent<HTMLInputElement>) =>
    setForm(f => ({ ...f, [e.target.name]: e.target.type === "number" ? +e.target.value : e.target.value }));

  const onSubmit = async () => {
    if (!form.name || !form.host || !form.model) {
      alert("Preencha todos os campos obrigatórios, verifique o nome, IP e Modelo do Equi");
      return;
    }

    try {
      await axios.post("http://localhost:3000/idface/terminals", form);
      alert({ title: "Terminal criado com sucesso!", status: "success", isClosable: true });
      nav("/list-terminals");
    } catch {
      alert("Erro ao criar terminal");
    }
  };


  return (
    <SidebarLayout>
      <Box bg="dark.soft" minH="100vh" px={6} py={8}>
        <Box maxW="800px" mx="auto">
          <HStack mb={4} gap={2}>
            <Icon as={FaArrowCircleLeft} color="white" />
            <Button size="sm" colorScheme="gray" onClick={() => nav("/list-terminals")}>
              Voltar
            </Button>
            <Heading size="lg" color="brand.500">Novo Terminal</Heading>
          </HStack>
          <Box bg="white" p={6} borderRadius="md" boxShadow="md">
            <VStack gap={4} align="stretch">
              {[
                { label: "Nome", name: "name", type: "text" },
                { label: "Host", name: "host", type: "text" },
                { label: "Porta", name: "port", type: "number" },
                { label: "Modelo", name: "model", type: "text" },
              ].map(fld => (
                <chakra.div key={fld.name}>
                  <Text fontSize="sm" mb={1}>{fld.label}</Text>
                  <Input
                    name={fld.name}
                    type={fld.type as any}
                    value={(form as any)[fld.name]}
                    onChange={onChange}
                    bg="gray.50"
                  />
                </chakra.div>
              ))}
              <HStack justify="flex-end" gap={3} pt={4}>
                <Button size="sm" colorScheme="brand" onClick={onSubmit}>
                  <Icon as={FaSave} mr={2} /> Salvar
                </Button>
              </HStack>
            </VStack>
          </Box>
        </Box>
      </Box>
    </SidebarLayout>
  );
}
