//    npm install @chakra-ui/select

import React, { useEffect, useState } from "react";
import {
  Box,
  Heading,
  HStack,
  VStack,
  Input,
  Button,
  Image,
  Text,
  Icon,
  Spinner,
  chakra,
} from "@chakra-ui/react";
import { FormControl, FormLabel } from "@chakra-ui/form-control";
import { Select } from "@chakra-ui/select";         // <–– aqui
import { FaArrowCircleLeft, FaSave } from "react-icons/fa";
import { useNavigate, useParams } from "react-router-dom";
import axios from "axios";
import SidebarLayout from "../../components/ui/SidebarLayout";

// 1) nossa lista de modelos:
const MODELS = [
  { value: "iDFace", label: "iDFace", imageSrc: "http://localhost:5173/src/assets/images/terminals/iDFace.jpg" },
  { value: "iDAccessPro", label: "iDAccess Pro", imageSrc: "http://localhost:5173/src/assets/images/terminals/iDAccess_pro.jpg" },
  // ... adicione quantos precisar
];

export default function EditTerminalPage() {
  const { id } = useParams<{ id: string }>();
  const isEditing = Boolean(id);
  const navigate = useNavigate();

  // 2) estado do terminal, incluindo o modelo
  const [terminal, setTerminal] = useState({
    model: MODELS[0].value,
    name: "",
    host: "",
    port: 80,
    ssl: false,
    user: "",
    password: "",
    passwordConf: "",
    netmask: "",
    gateway: "",
    rebootConfirm: false,
  });
  const [loading, setLoading] = useState(isEditing);

  // Carrega dados existentes
  useEffect(() => {
    if (isEditing) {
      axios.get(`/terminals/${id}`).then(({ data }) => {
        setTerminal({
          ...data,
          password: "",
          passwordConf: "",
        });
        setLoading(false);
      }).catch(() =>
        alert("Erro ao carregar os terminais")
      );
    }
  }, [id, isEditing, alert]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type, ariaChecked } = e.target;
    setTerminal(prev => ({
      ...prev,
      [name]: type === "checkbox" ? ariaChecked : value,
    }));
  };

  const handleSubmit = async () => {
    try {
      const payload = { ...terminal };
      if (isEditing) {
        await axios.put(`http://localhost:3000/idface/${id}`, payload);
        alert("Atualizado! Com Sucesso");
      } else {
        await axios.post("http://localhost:3000/idface", payload);
        alert("Criado! Com Sucesso");
      }
      navigate("/list-terminals");
    } catch {
        alert("Erro ao salvar");
    }
  };

  if (loading) {
    return (
      <SidebarLayout>
        <Box bg="dark.soft" minH="100vh" px={6} py={8}>
          <Spinner size="xl" color="brand.500" />
        </Box>
      </SidebarLayout>
    );
  }

  // 3) pega a URL da imagem do modelo selecionado
  const currentModel = MODELS.find(m => m.value === terminal.model)!;

  return (
    <SidebarLayout>
      <Box bg="dark.soft" minH="100vh" px={6} py={8}>
        <Box maxW="900px" mx="auto">
          {/* Header */}
          <HStack mb={4} gap={2}>
            <Icon as={FaArrowCircleLeft} color="white" />
            <Button size="sm" colorScheme="gray" onClick={() => navigate("/list-terminals")}>
              Voltar
            </Button>
            <Heading size="lg" color="brand.500">
              {isEditing ? "Editar Terminal" : "Novo Terminal"}
            </Heading>
          </HStack>

          <HStack align="flex-start" gap={8} wrap="wrap">
            {/* === Cartão da Foto do Modelo === */}
            <VStack bg="white" p={4} borderRadius="md" boxShadow="md" w="260px">
              <Image
                boxSize="200px"
                objectFit="contain"
                src={currentModel.imageSrc}
                alt={currentModel.label}
              />
              <Text fontWeight="bold" mt={2}>
                {currentModel.label}
              </Text>
            </VStack>

            {/* === Formulário === */}
            <Box flex="1" bg="white" p={6} borderRadius="md" boxShadow="md">
              <VStack align="stretch" gap={6}>
                {/* Modelo */}
                <FormControl>
                  <FormLabel>Modelo</FormLabel>
                  <Select
                    name="model"
                    value={terminal.model}
                    onChange={handleChange}
                  >
                    {MODELS.map(m => (
                      <option key={m.value} value={m.value}>
                        {m.label}
                      </option>
                    ))}
                  </Select>
                </FormControl>

                {/* Nome */}
                <FormControl isRequired>
                  <FormLabel>Nome *</FormLabel>
                  <Input
                    name="name"
                    placeholder="Nome do terminal"
                    value={terminal.name}
                    onChange={handleChange}
                    bg="gray.50"
                  />
                </FormControl>

                {/* Host / Porta */}
                <HStack gap={4}>
                  <FormControl isRequired>
                    <FormLabel>IP / DNS *</FormLabel>
                    <Input
                      name="host"
                      placeholder="Ex.: 192.168.1.10"
                      value={terminal.host}
                      onChange={handleChange}
                      bg="gray.50"
                    />
                  </FormControl>
                  <FormControl isRequired>
                    <FormLabel>Porta *</FormLabel>
                    <Input
                      name="port"
                      type="number"
                      value={terminal.port}
                      onChange={handleChange}
                      bg="gray.50"
                    />
                  </FormControl>
                </HStack>

                {/* Usuário / Senha */}
                <HStack gap={4}>
                  <FormControl isRequired>
                    <FormLabel>Usuário *</FormLabel>
                    <Input
                      name="user"
                      placeholder="admin"
                      value={terminal.user}
                      onChange={handleChange}
                      bg="gray.50"
                    />
                  </FormControl>
                  <FormControl isRequired>
                    <FormLabel>Senha *</FormLabel>
                    <Input
                      name="password"
                      type="password"
                      value={terminal.password}
                      onChange={handleChange}
                      bg="gray.50"
                    />
                  </FormControl>
                </HStack>

                {/* SSL */}
                <HStack>
                  <chakra.input
                    type="checkbox"
                    name="ssl"
                    checked={terminal.ssl}
                    onChange={handleChange}
                  />
                  <Text>SSL</Text>
                </HStack>

                {/* Botões */}
                <HStack justify="flex-end" gap={3}>
                  <Button size="sm" colorScheme="gray" onClick={() => navigate("/list-terminals")}>
                    Cancelar
                  </Button>
                  <Button size="sm" colorScheme="brand" onClick={handleSubmit}>
                    <Icon as={FaSave} mr={2} /> Salvar
                  </Button>
                </HStack>
              </VStack>
            </Box>
          </HStack>
        </Box>
      </Box>
    </SidebarLayout>
  );
}
