import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { ChakraProvider } from '@chakra-ui/react';
import theme from './theme';

import Login from './pages/Login';
import Register from './pages/Register';
import NotFound from './pages/NotFound';
import EquipamentoIDFacePage from './pages/EquipamentoIDFacePage';
import CadastrarPessoaPage from './pages/CadastrarPessoaPage';
import DashboardPessoasPage from './pages/DashboardPessoasPage';
import RegistroInicialPage from './pages/register/RegistroInicialPage';
import DashboardPage from './pages/dashboard/Dashboard';
import ListUsersPage from './pages/users/ListUsersPage';
import AddUserPage from './pages/users/AddUser';
import AddGroupsPage from './pages/users/AddGroupsUser';
import EditUserPage from './pages/users/EditUser';
import ImportCSVPage from './pages/users/ImportCsvUser';
import UsersCreditsPage from './pages/users/userCreditsPage';
import AddVisitorPage from './pages/visitors/AddVisitorPage';
import EditVisitorPage from './pages/visitors/EditVisitorPage';
import ListVisitorsPage from './pages/visitors/ListVisitorsPage';
import EditTerminalPage from './pages/terminal/EditTerminalPage';
import ListTerminalsPage from './pages/terminal/ListTerminalsPage';
import DownloadUsersPage from './pages/terminal/DownloadUsersPage';
import AddTerminalPage from './pages/terminal/AddTerminalPage';
import IDFaceConfigPage from './pages/terminal/TerminalIdFaceConfigPage';
import AddDepartmentPage from './pages/departamentos/AddDepartmentPage';
import EditDepartmentPage from './pages/departamentos/EditDepartmentPage';
import ListDepartmentsPage from './pages/departamentos/ListDepartmentsPage';

const App = () => {
  return (
    <ChakraProvider value={theme}>
      <Router>
        <Routes>
          <Route path="/" element={<Login />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/dashboard" element={<DashboardPage />} />
          <Route path="/equipamento-idface" element={<EquipamentoIDFacePage />} />
          <Route path="/cadastropessoa" element={<CadastrarPessoaPage />} />
          <Route path="/pessoas" element={<DashboardPessoasPage />} />
          <Route path="/registro-inicial" element={<RegistroInicialPage />} />
          <Route path="/list-users" element={<ListUsersPage />} />
          <Route path="/add-user" element={<AddUserPage />} />
          <Route path="/edit-user/:id" element={<EditUserPage />} />
          <Route path="/import-users" element={<ImportCSVPage />} />
          <Route path="/link-groups/:id" element={<AddGroupsPage />} />
          <Route path="/user-credits/:id" element={<UsersCreditsPage />} />
          <Route path="/list-visitors" element={<ListVisitorsPage />} />
          <Route path="/add-visitor" element={<AddVisitorPage />} />
          <Route path="/edit-visitor/:id" element={<EditVisitorPage />} />
          <Route path="/list-terminals" element={<ListTerminalsPage />} />
          <Route path="/add-terminal" element={<AddTerminalPage />} />
          <Route path="/edit-terminal/:id" element={<EditTerminalPage />} />
          <Route path="/idface-config/:id" element={<IDFaceConfigPage />} />
          <Route path="/list-departments" element={<ListDepartmentsPage />} />
          <Route path="/add-department" element={<AddDepartmentPage />} />
          <Route path="/edit-department/:id" element={<EditDepartmentPage />} />
          <Route
            path="/terminal/:id/download-users"
            element={<DownloadUsersPage />} />
          <Route path="*" element={<NotFound />} />
        </Routes>
      </Router>
    </ChakraProvider>
  );
};

export default App;