// src/pages/departamentos/AddDepartmentPage.tsx
import { useEffect, useState } from 'react';
import {
  Box,
  Heading,
  HStack,
  VStack,
  Text,
  chakra,
  Input,
  Button,
  Icon,
  useDisclosure,
  Spinner,
  Dialog,
  DialogContent,
  DialogHeader,
  DialogBody,
  DialogFooter,
} from '@chakra-ui/react';
import { Select } from '@chakra-ui/select';
import { useColorModeValue } from '@chakra-ui/color-mode'
import { FaArrowCircleLeft, FaSave, FaPlus } from 'react-icons/fa';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import SidebarLayout from '../../components/ui/SidebarLayout';
// Tabela: use chakra.* em vez de import explícito
const Table = chakra('table');
const Thead = chakra('thead');
const Tbody = chakra('tbody');
const Tr = chakra('tr');
const Th = chakra('th');
const Td = chakra('td');

interface Terminal { id: number; name: string; host: string; }
interface Person { id: number; nome: string; matricula: string; rg?: string; cpf?: string; email?: string; }
interface Visitor { id: number; nome: string; rg?: string; cpf?: string; email?: string; }

export default function AddDepartmentPage() {
  const navigate = useNavigate();
  const { open, onOpen, onClose } = useDisclosure();
  const bg = useColorModeValue('gray.50', 'gray.800');

  // estados
  const [name, setName] = useState('');
  const [terminalId, setTerminalId] = useState<number>(0);
  const [terminals, setTerminals] = useState<Terminal[]>([]);
  const [assignedPeople, setAssignedPeople] = useState<Person[]>([]);
  const [assignedVisitors, setAssignedVisitors] = useState<Visitor[]>([]);
  const [allPeople, setAllPeople] = useState<Person[]>([]);
  const [allVisitors, setAllVisitors] = useState<Visitor[]>([]);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'info' | 'pessoas'>('info');

  useEffect(() => {
    axios.get<Terminal[]>('http://localhost:3000/idface/terminals')
      .then(res => setTerminals(res.data))
      .catch(() => alert('Erro ao carregar terminais, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnico'));
  }, [alert]);

  const handleSave = async () => {
    if (!name.trim()) {
      return alert('Nome é obrigatório, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnico');
    }

    try {
      const payload = {
        nome: name,
        terminalId,
        userIds: Array.from(selectedIds)
          .filter(key => key.startsWith('person:'))
          .map(key => Number(key.split(':')[1])),
        visitorIds: Array.from(selectedIds)
          .filter(key => key.startsWith('visitor:'))
          .map(key => Number(key.split(':')[1])),
      };

      // Criação de novo departamento
      const res = await axios.post(`http://localhost:3000/departments`, {
        nome: name,
        terminalId,
      });
      const deptId = res.data.id;
      await axios.put(`http://localhost:3000/departments/${deptId}`, payload);
      alert({ title: 'Departamento criado!, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco'});

      navigate('/list-departments');
    } catch (e: any) {
      alert(
        'Erro ao Salvar Departamento, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco'
      );
    }
  };

  const openAssign = async () => {
    setLoading(true);
    try {
      const [pRes, vRes] = await Promise.all([
        axios.get<Person[]>('http://localhost:3000/pessoas'),
        axios.get<Visitor[]>('http://localhost:3000/visitors'),
      ]);
      setAllPeople(pRes.data);
      setAllVisitors(vRes.data);
      onOpen();
    } finally {
      setLoading(false);
    }
  };

  const toggleSelect = (kind: 'person' | 'visitor', id: number) => {
    const key = `${kind}:${id}`;
    setSelectedIds(prev => {
      const s = new Set(prev);
      s.has(key) ? s.delete(key) : s.add(key);
      return s;
    });
  };

  return (
    <SidebarLayout>
      <Box bg={bg} minH="100vh" p={6}>
        {/* header */}
        <HStack mb={4}>
          <Icon as={FaArrowCircleLeft} />
          <Button variant="ghost" size="sm" onClick={() => navigate('/list-departments')}>Cancelar</Button>
          <Heading size="lg">Novo Departamento</Heading>
        </HStack>

        {/* abas manuais */}
        <HStack borderBottom="1px solid" borderColor="gray.200" mb={4}>
          <Button flex={1} variant={activeTab === 'info' ? 'solid' : 'ghost'} onClick={() => setActiveTab('info')}>
            Informações Gerais
          </Button>
          <Button flex={1} variant={activeTab === 'pessoas' ? 'solid' : 'ghost'} onClick={() => setActiveTab('pessoas')}>
            Pessoas
          </Button>
        </HStack>

        {activeTab === 'info' && (
          <VStack gap={4} align="stretch">
            <Box>
              <Text>Nome <chakra.span color="red.500">*</chakra.span></Text>
              <Input placeholder="Nome do departamento" value={name} onChange={e => setName(e.target.value)} />
            </Box>
            <Box>
              <Text>Terminal iDFace</Text>
              <Select placeholder="Selecione" value={terminalId || ''} onChange={e => setTerminalId(Number(e.target.value))}>
                {terminals.map(t => (
                  <option key={t.id} value={t.id}>{t.name} ({t.host})</option>
                ))}
              </Select>
            </Box>
          </VStack>
        )}

        {activeTab === 'pessoas' && (
          <>
            <HStack justify="space-between" mb={2}>
              <Text fontWeight="bold">Pessoas vinculadas</Text>
              <Button size="sm" onClick={openAssign}> <Icon as={FaPlus} />Adicionar</Button>
            </HStack>
            <Table w="full" aria-variant="simple">
              <Thead>
                <Tr><Th>Nome</Th><Th>Matrícula</Th></Tr>
              </Thead>
              <Tbody>
                {(assignedPeople.length + assignedVisitors.length) ? (
                  <>
                    {assignedPeople.map(p => (
                      <Tr key={`p${p.id}`}>
                        <Td>{p.nome}</Td><Td>{p.matricula}</Td>
                      </Tr>
                    ))}
                    {assignedVisitors.map(v => (
                      <Tr key={`v${v.id}`}>
                        <Td>{v.nome}</Td><Td>—</Td>
                      </Tr>
                    ))}
                  </>
                ) : (
                  <Tr><Td colSpan={2}>Nenhum registro</Td></Tr>
                )}
              </Tbody>
            </Table>
          </>
        )}

        {/* ações */}
        <HStack justify="flex-end" mt={6}>
          <Button variant="outline" onClick={() => navigate('/list-departments')}>Cancelar</Button>
          <Button colorScheme="teal" onClick={handleSave}>
            <Icon as={FaSave} />
            Salvar
          </Button>
        </HStack>

        {/* Dialog de vincular */}
        <Dialog.Root open={open} onOpenChange={onClose}>
          <DialogContent>
            <DialogHeader>Adicionar Pessoas/Visitantes</DialogHeader>
            <DialogBody>
              {loading ? (
                <Spinner />
              ) : (
                <VStack gap={4} align="stretch">
                  <Text fontWeight="bold">Pessoas</Text>
                  <Table aria-variant="unstyled">
                    <Thead>
                      <Tr><Th /><Th>Nome</Th><Th>Matrícula</Th><Th>RG</Th><Th>CPF</Th><Th>Email</Th></Tr>
                    </Thead>
                    <Tbody>
                      {allPeople.map(p => (
                        <Tr key={p.id}>
                          <Td><chakra.input
                            type="checkbox" checked={selectedIds.has(`person:${p.id}`)} onChange={() => toggleSelect('person', p.id)} /></Td>
                          <Td>{p.nome}</Td><Td>{p.matricula}</Td><Td>{p.rg}</Td><Td>{p.cpf}</Td><Td>{p.email}</Td>
                        </Tr>
                      ))}
                    </Tbody>
                  </Table>
                  <Text fontWeight="bold">Visitantes</Text>
                  <Table aria-variant="unstyled" bgSize="sm">
                    <Thead>
                      <Tr><Th /><Th>Nome</Th><Th>RG</Th><Th>CPF</Th><Th>Email</Th></Tr>
                    </Thead>
                    <Tbody>
                      {allVisitors.map(v => (
                        <Tr key={v.id}>
                          <Td><chakra.input
                            type="checkbox" checked={selectedIds.has(`visitor:${v.id}`)} onChange={() => toggleSelect('visitor', v.id)} /></Td>
                          <Td>{v.nome}</Td><Td>{v.rg}</Td><Td>{v.cpf}</Td><Td>{v.email}</Td>
                        </Tr>
                      ))}
                    </Tbody>
                  </Table>
                </VStack>
              )}
            </DialogBody>
            <DialogFooter>
              <Button variant="ghost" mr={3} onClick={onClose}>Cancelar</Button>
              <Button
                colorScheme="teal"
                onClick={() => {
                  const people = allPeople.filter(p => selectedIds.has(`person:${p.id}`));
                  const visitors = allVisitors.filter(v => selectedIds.has(`visitor:${v.id}`));
                  setAssignedPeople(people);
                  setAssignedVisitors(visitors);
                  onClose();
                }}
              >
                Adicionar
              </Button>

            </DialogFooter>
          </DialogContent>
        </Dialog.Root>
      </Box>
    </SidebarLayout>
  );
}
