// src/pages/users/EditUserPage.tsx
import React, { useEffect, useRef, useState } from "react";
import {
  Box,
  Heading,
  HStack,
  VStack,
  Input,
  Button,
  Image,
  Text,
  Icon,
  chakra,
  Spinner,
} from "@chakra-ui/react";
import { Select } from "@chakra-ui/select";
import { useColorModeValue } from "@chakra-ui/color-mode";
import {
  FaCamera,
  FaArrowCircleLeft,
  FaSave,
  FaFingerprint,
  FaCreditCard,
  FaQrcode,
  FaBuilding,
  FaInfoCircle,
} from "react-icons/fa";
import { useNavigate, useParams } from "react-router-dom";
import axios from "axios";
import SidebarLayout from "../../components/ui/SidebarLayout";

interface Department {
  id: number;
  nome: string;
  terminal: { id: number; name: string; host: string };
}

interface Group {
  id: number;
  nome: string;
}

interface UserForm {
  nome: string;
  matricula: string;
  idUsuario: string;
  rg: string;
  cpf: string;
  email: string;
  telefone: string;
  senha: string;
  confirmarSenha: string;
  observacoes: string;
  departmentId: number;
  terminalId: number;
  userIdIdface: number;
  grupos: number[];
  administrador: boolean;
  inativo: boolean;
  listaExcecao: boolean;
}

const INITIAL_FORM: UserForm = {
  nome: "",
  matricula: "",
  idUsuario: "",
  rg: "",
  cpf: "",
  email: "",
  telefone: "",
  senha: "",
  confirmarSenha: "",
  observacoes: "",
  departmentId: 0,
  terminalId: 0,
  userIdIdface: 0,
  grupos: [],
  administrador: false,
  inativo: false,
  listaExcecao: false,
};

declare global {
  interface ImportMeta {
    env: { VITE_API_URL?: string;[key: string]: any };
  }
}
const API_URL = import.meta.env.VITE_API_URL || "http://localhost:3000";

type Params = { id: string };
type TabKey = "geral" | "deptos" | "digitais" | "cartoes" | "qrcode" | "info";

const TABS: { key: TabKey; label: React.ReactNode }[] = [
  { key: "geral", label: "Geral" },
  { key: "deptos", label: <><FaBuilding /> Deptos./Grupos</> },
  { key: "digitais", label: <><FaFingerprint /> Digitais</> },
  { key: "cartoes", label: <><FaCreditCard /> Cartões</> },
  { key: "qrcode", label: <><FaQrcode /> QR Code</> },
  { key: "info", label: <><FaInfoCircle /> Info</> },
];

export default function EditUserPage() {
  const navigate = useNavigate();
  const { id } = useParams<Params>();
  const bg = useColorModeValue("gray.50", "gray.800");

  const [activeTab, setActiveTab] = useState<TabKey>("geral");
  const [form, setForm] = useState<UserForm>({ ...INITIAL_FORM });
  const [departments, setDepartments] = useState<Department[]>([]);
  const [groups, setGroups] = useState<Group[]>([]);
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [foto, setFoto] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [showCamera, setShowCamera] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // 1) carrega lista de departamentos
  useEffect(() => {
    axios
      .get<Department[]>(`${API_URL}/departments`)
      .then(res => setDepartments(res.data))
      .catch(() =>
        alert("Erro ao carregar departamentos.")
      );
  }, [alert]);

  // 2) busca dados da pessoa por id
  useEffect(() => {
    if (!id) return;
    axios
      .get<UserForm & { fotoUrl?: string }>(`${API_URL}/pessoas/${id}`)
      .then(res => {
        const data = res.data;
        setForm({
          ...data,
          senha: "",
          confirmarSenha: "",
          grupos: data.grupos || [],
        });
        if (data.fotoUrl) {
          setPreview(data.fotoUrl);
        }
      })
      .catch(() =>
        alert("Erro ao carregar usuário.")
      )
      .finally(() => setLoading(false));
  }, [id, alert]);

  // 3) carrega grupos sempre que departmentId mudar
  useEffect(() => {
    if (!form.departmentId) return;
    const loadGroups = async () => {
      try {
        // tenta buscar grupos
        const { data: fetched } = await axios.get<Group[]>(
          `${API_URL}/departments/${form.departmentId}/groups`
        );
        if (fetched.length === 0) {
          // cria padrão
          await axios.post(`${API_URL}/groups`, {
            nome: "Grupo Padrão",
            descricao: "Criado automaticamente",
            departmentId: form.departmentId,
            type: 3,
          });
          const { data: created } = await axios.get<Group[]>(
            `${API_URL}/departments/${form.departmentId}/groups`
          );
          setGroups(created);
        } else {
          setGroups(fetched);
        }
      } catch (err) {
        alert("Erro ao carregar ou criar grupos");
      }
    };
    loadGroups();
  }, [form.departmentId, alert]);

  // handleChange genérico
  const handleChange = <K extends keyof UserForm>(
    field: K,
    value: string | boolean | number | number[]
  ) => {
    setForm(prev => {
      const next = { ...prev, [field]: value } as UserForm;
      if (field === "departmentId") {
        const dep = departments.find(d => d.id === Number(value));
        next.terminalId = dep?.terminal.id ?? 0;
        next.grupos = []; // reset ao trocar depto
      }
      return next;
    });
  };

  // upload de foto
  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] ?? null;
    setFoto(file);
    if (file) setPreview(URL.createObjectURL(file));
  };

  // abrir câmera
  const openCamera = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch {
      alert("Erro ao acessar câmera.");
      setShowCamera(false);
    }
  };
  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current) return;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      alert("Falha interna.");
      return;
    }
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    canvas.toBlob(blob => {
      if (blob) {
        const file = new File([blob], "foto.jpg", { type: "image/jpeg" });
        setFoto(file);
        setPreview(URL.createObjectURL(file));
      }
    }, "image/jpeg", 0.9);
    (video.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    setShowCamera(false);
  };

  // salvar alterações
  const handleSubmit = async () => {
    if (!form.departmentId) {
      alert("Selecione um departamento.");
      return;
    }
    if (form.senha && form.senha !== form.confirmarSenha) {
      alert("Senhas não coincidem.");
      return;
    }

    setIsSubmitting(true);
    try {
      if (foto) {
        const fd = new FormData();
        fd.append("foto", foto);

        const response = await axios.post(
          `http://localhost:3000/idface/user_test_image/${form.terminalId}`,
          fd,
          { headers: { 'Content-Type': 'application/octet-stream' } }
        );

        if (response.data?.success != true) {
          console.log(JSON.stringify(response))

          throw new Error("A imagem não foi aceita pelo terminal iDFace.");
        }
      }
      // 1) atualiza pessoa
      const { data: pessoaId } = await axios.put<number>(
        `${API_URL}/pessoas/${id}`,
        {
          nome: form.nome,
          matricula: form.matricula,
          idUsuario: form.idUsuario,
          rg: form.rg,
          cpf: form.cpf,
          email: form.email,
          telefone: form.telefone,
          observacoes: form.observacoes,
          departmentId: form.departmentId,
          terminalId: form.terminalId,
          userIdIdface: form.userIdIdface,
          grupos: form.grupos,
          administrador: form.administrador,
          inativo: form.inativo,
          listaExcecao: form.listaExcecao,
          senha: form.senha || undefined,
        }
      );

      // 2) se tiver foto, envia ao iDFace
      if (foto) {
        const fd = new FormData();
        fd.append("foto", foto);
        fd.append("user_id", String(pessoaId));
        await axios.put(
          `${API_URL}/idface/foto/${form.terminalId}`,
          fd,
          { headers: { "Content-Type": "multipart/form-data" } }
        );
      }

      // 3) atualiza credenciais do sistema
      await axios.put(`${API_URL}/users/${id}`, {
        nome: form.nome,
        pessoaId,
        userIdIdface: form.userIdIdface,
        senha: form.senha || undefined,
        administrador: form.administrador,
        inativo: form.inativo,
        listaExcecao: form.listaExcecao,
      });

      alert(JSON.stringify({ title: "Usuário atualizado!", status: "success", isClosable: true }));
      navigate("/list-users");
    } catch (err: any) {
      alert("Erro ao atualizar.",
       );
    } finally {
      setIsSubmitting(false);
    }
  }; // ← aqui encerra handleSubmit

  // renderLoading
  if (loading) {
    return (
      <SidebarLayout>
        <Box bg={bg} minH="100vh" p={6} display="flex" alignItems="center" justifyContent="center">
          <Spinner size="xl" />
        </Box>
      </SidebarLayout>
    );
  }

  // renderPrincipal
  return (
    <SidebarLayout>
      <Box bg={bg} minH="100vh" p={6}>
        <Box maxW="900px" mx="auto">
          {/* Cabeçalho */}
          <HStack mb={6} gap={2}>
            <Icon as={FaArrowCircleLeft} boxSize={6} color="gray.500" />
            <Button variant="ghost" onClick={() => navigate("/list-users")}>
              Voltar
            </Button>
            <Heading size="lg">Editar Pessoa</Heading>
          </HStack>

          <HStack align="flex-start" gap={4}>
            {/* Foto & câmera */}
            <VStack w="260px" bg="white" p={4} rounded="md" shadow="sm">
              <Box rounded="full" overflow="hidden" boxSize="150px" bg="gray.100">
                <Image
                  src={preview ?? `${API_URL}/uploads/profile_user.jpg`}
                  alt="Preview"
                  boxSize="150px"
                  objectFit="cover"
                />
              </Box>
              <Input type="file" accept="image/*" size="sm" onChange={handleFotoUpload} />
              <Button size="sm" variant="outline" onClick={openCamera}>
                <Icon as={FaCamera} mr={2} /> Tirar Foto
              </Button>
              {showCamera && (
                <VStack>
                  <video ref={videoRef} autoPlay style={{ width: "100%", borderRadius: 8 }} />
                  <Button size="sm" onClick={capturePhoto}>
                    Capturar
                  </Button>
                  <canvas ref={canvasRef} style={{ display: "none" }} />
                </VStack>
              )}
            </VStack>

            {/* Formulário */}
            <Box flex={1} bg="white" p={6} rounded="md" shadow="sm">
              {/* Abas */}
              <HStack borderBottom="1px solid" borderColor="gray.200" mb={4}>
                {TABS.map(tab => (
                  <Button
                    key={tab.key}
                    flex={1}
                    variant={activeTab === tab.key ? "solid" : "ghost"}
                    colorScheme={activeTab === tab.key ? "brand" : "gray"}
                    onClick={() => setActiveTab(tab.key)}
                  >
                    {tab.label}
                  </Button>
                ))}
              </HStack>

              {/* Aba Geral */}
              {activeTab === "geral" && (
                <VStack align="stretch" gap={4}>
                  {["nome", "matricula", "idUsuario", "rg", "cpf", "email", "telefone"].map(f => (
                    <Input
                      key={f}
                      placeholder={f.charAt(0).toUpperCase() + f.slice(1)}
                      value={(form as any)[f]}
                      onChange={e => handleChange(f as any, e.target.value)}
                    />
                  ))}
                  <Input
                    type="password"
                    placeholder="Senha"
                    value={form.senha}
                    onChange={e => handleChange("senha", e.target.value)}
                  />
                  <Input
                    type="password"
                    placeholder="Confirmar senha"
                    value={form.confirmarSenha}
                    onChange={e => handleChange("confirmarSenha", e.target.value)}
                  />
                  <Input
                    placeholder="Observações"
                    value={form.observacoes}
                    onChange={e => handleChange("observacoes", e.target.value)}
                  />
                  <Input
                    type="number"
                    placeholder="ID no iDFace"
                    value={form.userIdIdface || ""}
                    readOnly
                    borderColor="gray.300"
                    _readOnly={{ bg: "gray.100", cursor: "not-allowed" }}
                  />
                  <HStack gap={6}>
                    {(["administrador", "inativo", "listaExcecao"] as const).map(key => (
                      <HStack key={key}>
                        <chakra.input
                          type="checkbox"
                          checked={form[key]}
                          onChange={e => handleChange(key, e.target.checked)}
                        />
                        <Text>{key.charAt(0).toUpperCase() + key.slice(1)}</Text>
                      </HStack>
                    ))}
                  </HStack>
                </VStack>
              )}

              {/* Aba Deptos./Grupos */}
              {activeTab === "deptos" && (
                <VStack align="stretch" gap={4}>
                  <Box>
                    <Text fontSize="sm">
                      Departamento <chakra.span color="red.500">*</chakra.span>
                    </Text>
                    <Select
                      placeholder="Selecione um departamento"
                      value={form.departmentId || ""}
                      onChange={e => handleChange("departmentId", Number(e.target.value))}
                    >
                      {departments.map(d => (
                        <option key={d.id} value={d.id}>
                          {d.nome} — {d.terminal.name}
                        </option>
                      ))}
                    </Select>
                  </Box>
                  <Box>
                    <Text fontSize="sm">Grupos</Text>
                    <Select
                      placeholder="Selecione vários grupos"
                      multiple
                      value={form.grupos.map(String)}
                      onChange={e => {
                        const opts = Array.from(e.target.selectedOptions).map(o => Number(o.value));
                        handleChange("grupos", opts);
                      }}
                    >
                      {groups.map(g => (
                        <option key={g.id} value={g.id}>
                          {g.nome}
                        </option>
                      ))}
                    </Select>
                  </Box>
                </VStack>
              )}

              {/* Outras abas em desenvolvimento */}
              {activeTab !== "geral" && activeTab !== "deptos" && (
                <VStack align="center" py={10} gap={4}>
                  <Icon
                    as={{
                      digitais: FaFingerprint,
                      cartoes: FaCreditCard,
                      qrcode: FaQrcode,
                      info: FaInfoCircle,
                    }[activeTab]}
                    boxSize={8}
                    color="gray.400"
                  />
                  <Text color="gray.500">Funcionalidade em desenvolvimento</Text>
                </VStack>
              )}

              {/* Botões Salvar/Cancelar */}
              <HStack justify="flex-end" pt={6} gap={3}>
                <Button variant="outline" onClick={() => navigate("/list-users")}>
                  Cancelar
                </Button>
                <Button
                  colorScheme="brand"
                  onClick={handleSubmit}
                  loading={isSubmitting}
                >
                  <Icon as={FaSave} mr={2} /> Salvar
                </Button>
              </HStack>
            </Box>
          </HStack>
        </Box>
      </Box>
    </SidebarLayout>
  );
}
