// src/pages/terminals/ListTerminalsPage.tsx
import { useEffect, useState } from "react";
import {
  Box, Heading, HStack, VStack, Input, Button, Icon, chakra,
} from "@chakra-ui/react";
import { FaPlus, FaTrash, FaDownload, FaSearch, FaEdit, FaCog } from "react-icons/fa";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import SidebarLayout from "../../components/ui/SidebarLayout";

type Terminal = {
  id: number;
  name: string;
  host: string;
  port: number;
  model: string;
  status: string;
};

export default function ListTerminalsPage() {
  const navigate = useNavigate();
  const [terminals, setTerminals] = useState<Terminal[]>([]);
  const [selected, setSelected] = useState<number[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [showFilter, setShowFilter] = useState(false);

  useEffect(() => {
    axios.get("http://localhost:3000/idface/terminals")
      .then(res => setTerminals(res.data))
      .catch(() =>
        alert("Erro ao carregar terminais")
      );
  }, [alert]);

  const toggleSelect = (id: number) =>
    setSelected(s => s.includes(id) ? s.filter(x => x !== id) : [...s, id]);

  const toggleSelectAll = () =>
    setSelected(sel => sel.length === terminals.length ? [] : terminals.map(t => t.id));

  const removeSelected = () => {
    // Apenas local; troque por DELETE no backend se for o caso
    setTerminals(t => t.filter(x => !selected.includes(x.id)));
    setSelected([]);
    alert("Terminais removidos");
  };

  const filtered = terminals.filter(t =>
    t.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <SidebarLayout>
      <Box bg="dark.soft" minH="100vh" px={6} py={8}>
        <Box maxW="1200px" mx="auto">
          <Heading size="lg" mb={6} color="brand.500">
            Gerenciamento de Terminais
          </Heading>

          <VStack align="stretch" gap={4}>
            {/* Ações e Busca */}
            <HStack justify="space-between" wrap="wrap" gap={4}>
              <HStack gap={3}>
                <Button colorScheme="brand" onClick={() => navigate("/add-terminal")}>
                  <Icon as={FaPlus} mr={2} /> Adicionar
                </Button>
                <Button colorScheme="red" onClick={removeSelected} disabled={!selected.length}>
                  <Icon as={FaTrash} mr={2} /> Remover {selected.length > 0 && `(${selected.length})`}
                </Button>
                <Button variant="outline" colorScheme="brand" onClick={() => setShowFilter(v => !v)}>
                  Filtrar
                </Button>
              </HStack>
              <HStack gap={3}>
                <Button colorScheme="brand">
                  <Icon as={FaDownload} mr={2} /> Exportar CSV
                </Button>
              </HStack>
            </HStack>

            <HStack gap={2} maxW="400px">
              <Icon as={FaSearch} color="gray.300" />
              <Input
                placeholder="Pesquisar por nome..."
                bg="gray.50"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                _placeholder={{ color: "gray.400" }}
              />
            </HStack>

            {showFilter && (
              <Box bg="white" p={4} borderRadius="md" boxShadow="sm">
                <HStack gap={3} wrap="wrap">
                  <Input placeholder="Buscar por host" bg="gray.50" size="sm" maxW="200px" />
                  <Input placeholder="Buscar por modelo" bg="gray.50" size="sm" maxW="200px" />
                  <Button colorScheme="brand" size="sm">Aplicar Filtro</Button>
                </HStack>
              </Box>
            )}
          </VStack>

          {/* Tabela */}
          <Box mt={4} overflowX="auto" bg="white" borderRadius="md" boxShadow="base">
            <chakra.table width="100%">
              <chakra.thead bg="gray.800">
                <chakra.tr>
                  {["", "ID", "Nome", "Host", "Porta", "Modelo", "Status", "Ações"].map((h, i) => (
                    <chakra.th
                      key={i}
                      px={4} py={3}
                      textAlign={i === 2 ? "left" : "center"}
                      color="white"
                      fontSize="sm"
                    >
                      {i === 0
                        ? <chakra.input
                            type="checkbox"
                            checked={selected.length === terminals.length && terminals.length > 0}
                            onChange={toggleSelectAll}
                          />
                        : h}
                    </chakra.th>
                  ))}
                </chakra.tr>
              </chakra.thead>
              <chakra.tbody>
                {filtered.map(t => (
                  <chakra.tr key={t.id} _odd={{ bg: "gray.50" }}>
                    <chakra.td px={4} py={2} textAlign="center">
                      <chakra.input
                        type="checkbox"
                        checked={selected.includes(t.id)}
                        onChange={() => toggleSelect(t.id)}
                      />
                    </chakra.td>
                    <chakra.td px={4} py={2} textAlign="center">{t.id}</chakra.td>
                    <chakra.td px={4} py={2} textAlign="left">{t.name}</chakra.td>
                    <chakra.td px={4} py={2} textAlign="center">{t.host}</chakra.td>
                    <chakra.td px={4} py={2} textAlign="center">{t.port}</chakra.td>
                    <chakra.td px={4} py={2} textAlign="center">{t.model}</chakra.td>
                    <chakra.td
                      px={4} py={2} textAlign="center"
                      color={t.status === "Online" ? "green.600" : "red.500"}
                    >
                      {t.status}
                    </chakra.td>
                    <chakra.td px={4} py={2} textAlign="center">
                      <HStack justify="center" gap={2}>
                        <Button
                          size="xs"
                          colorScheme="blue"
                          onClick={() => navigate(`/edit-terminal/${t.id}`)}
                        >
                          <Icon as={FaEdit} mr={1} /> Editar
                        </Button>
                        {t.model === "iDFace" && (
                          <Button
                            size="xs"
                            colorScheme="teal"
                            onClick={() => navigate(`/idface-config/${t.id}`)}
                          >
                            <Icon as={FaCog} mr={1} /> Configurar
                          </Button>
                        )}
                      </HStack>
                    </chakra.td>
                  </chakra.tr>
                ))}
              </chakra.tbody>
            </chakra.table>
          </Box>
        </Box>
      </Box>
    </SidebarLayout>
  );
}
