import {
  Box, Button, FieldRoot, FieldLabel, Heading, Input, VStack, Image, Text
} from '@chakra-ui/react';
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useToast } from '@chakra-ui/toast';

export default function RegistroInicialPage() {
  const navigate = useNavigate();
  const toast = useToast();
  const [form, setForm] = useState({
    name: '',
    email: '',
    companyName: '',
    cnpj: '',
    responsible: ''
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async () => {
    if (!form.name || !form.email || !form.companyName || !form.cnpj || !form.responsible) {
      toast({ title: 'Necessário Preencher os Campos Obrigatórios', status: 'error' });
      return;
    }

    try {
      await axios.post('http://localhost:3000/api/license/signUp', {
        name: form.name,
        companyName: form.companyName,
        email: form.email,          
        cnpj: form.cnpj,
        responsible: form.responsible,
      });

      toast({ title: 'Cadastro realizado com sucesso!', status: 'success' });
      navigate('/login');
    } catch (err: any) {
      toast({
        title: 'Erro ao registrar',
        description: err?.response?.data?.message || 'Erro inesperado',
        status: 'error',
      });
    }
  };

  return (
    <Box
      minH="100vh"
      bg="dark.soft"
      display="flex"
      alignItems="center"
      justifyContent="center"
      px={4}
    >
      <Box
        bg="white"
        borderRadius="xl"
        boxShadow="2xl"
        p={8}
        maxW="lg"
        w="full"
      >
        <VStack letterSpacing={5} align="stretch">
          <Box textAlign="center">
            <Image
              src="http://localhost:3000/uploads/logoTechtra.png"
              alt="Logo Tectra"
              maxW="160px"
              mx="auto"
              mb={4}
            />
            <Heading size="lg" color="brand.500">
              Bem-vindo ao Tectra Accesso
            </Heading>
            <Text fontSize="sm" color="gray.500">
              Por favor, cadastre-se para prosseguir.
            </Text>
          </Box>

          {[
            { label: 'Nome Completo', name: 'name' },
            { label: 'Email', name: 'email', type: 'email' },
            { label: 'Nome da Empresa', name: 'companyName' },
            { label: 'CNPJ', name: 'cnpj' , mask: '99.999.999/9999-99'},
            { label: 'Fornecedor', name: 'responsible' },
          ].map(({ label, name, type = 'text' }) => (
            <FieldRoot key={name} aria-required="true" width="full">
              <FieldLabel>{label}</FieldLabel>
              <Input
                name={name}
                type={type}
                fontVariationSettings="filled"
                value={form[name as keyof typeof form]}
                onChange={handleChange}
              />
            </FieldRoot>
          ))}

          <Button
            colorScheme="brand"
            onClick={handleSubmit}
            size="lg"
            mt={4}
          >
            REGISTRAR
          </Button>
        </VStack>
      </Box>
    </Box>
  );
}
