// src/pages/users/ImportCSVPage.tsx
import {
    Box,
    Heading,
    VStack,
    Input,
    Button,
    Icon,
    Text,
    HStack,
} from "@chakra-ui/react";
import { useToast } from "@chakra-ui/toast";
import { FaUpload, FaArrowCircleLeft } from "react-icons/fa";
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import SidebarLayout from "../../components/ui/SidebarLayout";

export default function ImportCSVPage() {
    const toast = useToast();
    const navigate = useNavigate();
    const [csvFile, setCsvFile] = useState<File | null>(null);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            setCsvFile(file);
        }
    };

    const handleImport = async () => {
        if (!csvFile) {
            toast({
                title: "Selecione um arquivo CSV antes de importar",
                status: "warning",
                isClosable: true,
            });
            return;
        }
        const formData = new FormData();
        formData.append("file", csvFile);

        try {
            // TODO: ajuste a rota conforme seu backend (ex.: /pessoas/import-csv)
            await axios.post("http://localhost:3000/pessoas/import-csv", formData, {
                headers: { "Content-Type": "multipart/form-data" },
            });
            toast({
                title: "CSV importado com sucesso",
                status: "success",
                isClosable: true,
            });
            navigate("/list-users");
        } catch {
            toast({
                title: "Erro ao importar CSV",
                status: "error",
                isClosable: true,
            });
        }
    };

    return (
        <SidebarLayout>
            <Box bg="dark.soft" minH="100vh" px={6} py={8}>
                <Box maxW="600px" mx="auto">
                    <VStack gap={6} align="stretch">
                        <HStack gap={2}>
                            <Icon as={FaArrowCircleLeft} />
                            <Button
                                onClick={() => navigate("/list-users")}
                                colorScheme="gray"
                                size="sm"
                            >
                                Voltar
                            </Button>
                            <Heading size="lg" color="brand.500">
                                Importar Usuários via CSV
                            </Heading>
                        </HStack>

                        <Box bg="white" p={6} borderRadius="md" boxShadow="md">
                            <VStack gap={4} align="stretch">
                                <Text fontSize="sm">
                                    Selecione um arquivo <Text as="span" fontWeight="bold">.csv</Text>{" "}
                                    contendo usuários. Cada linha deve ter: nome, matricula, rg, cpf,
                                    telefone, cargo, ativo (true/false), listaExcecao (true/false),
                                    administrador (true/false), email.
                                </Text>
                                <Input
                                    type="file"
                                    accept=".csv"
                                    onChange={handleFileChange}
                                    bg="gray.50"
                                />
                                <HStack gap={3} justify="flex-end" pt={4}>
                                    <Icon as={FaUpload} />
                                    <Button
                                        as={FaUpload}
                                        colorScheme="brand"
                                        onClick={handleImport}
                                    >
                                        Importar
                                    </Button>
                                </HStack>
                            </VStack>
                        </Box>
                    </VStack>
                </Box>
            </Box>
        </SidebarLayout>
    );
}
