// src/pages/visitors/ListVisitorsPage.tsx
import { useEffect, useState } from "react";
import {
  Box,
  Heading,
  HStack,
  Button,
  Input,
  Icon,
  chakra
} from "@chakra-ui/react";
import {
  FaPlus,
  FaTrash,
  FaFilter,
  FaUpload,
  FaPrint,
  FaDownload,
  FaSearch,
  FaEdit,
} from "react-icons/fa";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import SidebarLayout from "../../components/ui/SidebarLayout";

type Visitante = {
  id: number;
  nome: string; // <- CORRETO para refletir a entidade Pessoa
  cpf?: string;
  rg?: string;
  visitorCompany?: string;
  visitedCompanyName?: string;
  phone?: string;
  email?: string;
  shelfLifeDate: string;
  shelfLifeTime: string;
  user_id: number;
};


export default function ListVisitorsPage() {
  const navigate = useNavigate();
  const [visitantes, setVisitantes] = useState<Visitante[]>([]);
  const [selecionados, setSelecionados] = useState<number[]>([]);
  const [showFiltro, setShowFiltro] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  // Carrega lista de visitantes do backend
  useEffect(() => {
    axios
      .get("http://localhost:3000/visitors")
      .then((res) => setVisitantes(res.data))
      .catch(() =>
        alert("Erro ao carregar visitantes")
      );
  }, [alert]);

  // Alterna seleção de um visitante
  const toggleSelecionado = (id: number) => {
    setSelecionados((prev) =>
      prev.includes(id) ? prev.filter((pid) => pid !== id) : [...prev, id]
    );
  };

  const removerPessoa = async (id: number) => {
    try {
      await axios.delete(`http://localhost:3000/visitors/${id}/1`);
      setVisitantes((prev) => prev.filter((p) => p.id !== id));
      alert("Pessoa excluída com sucesso");
    } catch (err) {
      console.error(err);
      alert("Erro ao excluir pessoa");
    }
  };

  // Seleciona ou desmarca todos
  const toggleSelecionarTodos = () => {
    if (selecionados.length === visitantes.length) {
      setSelecionados([]);
    } else {
      setSelecionados(visitantes.map((v) => v.id));
    }
  };
  // Apaga localmente (ou chame DELETE ao backend conforme necessário)
  const removerSelecionados = async () => {
    try {
      await Promise.all(
        selecionados.map(async (user_id) =>
          axios.delete(`http://localhost:3000/visitors/${user_id}/1`)
        )
      );
      setVisitantes((prev) => prev.filter((p) => !selecionados.includes(p.id)));
      setSelecionados([]);
      alert("Pessoa excluída com sucesso");
    } catch (err) {
      console.error(err);
      alert("Erro ao excluir pessoa")
    }
  };

  // Filtra visitantes por nome
  const visitantesFiltrados = visitantes.filter(v =>
    v.nome?.toLowerCase().includes(searchTerm.toLowerCase())
  );


  return (
    <SidebarLayout>
      <Box bg="dark.soft" minH="100vh" px={6} py={8}>
        <Box maxW="1200px" mx="auto">
          <Heading size="lg" mb={6} color="brand.500">
            Cadastro de Visitantes
          </Heading>

          {/* ===== Barra Superior: botões + pesquisa ===== */}
          <HStack justify="space-between" mb={4} wrap="wrap" gap={4}>
            <HStack gap={3}>
              <Button
                colorScheme="brand"
                onClick={() => navigate("/add-visitor")}
                _hover={{ bg: "brand.600" }}
              >
                <Icon as={FaPlus} mr={2} /> Adicionar
              </Button>
              <Button
                colorScheme="red"
                onClick={removerSelecionados}
                disabled={selecionados.length === 0}
                _disabled={{ opacity: 0.6, cursor: "not-allowed" }}
              >
                <Icon as={FaTrash} mr={2} /> Remover{" "}
                {selecionados.length > 0 && `(${selecionados.length})`}
              </Button>
              <Button
                variant="outline"
                colorScheme="brand"
                onClick={() => setShowFiltro((v) => !v)}
                _hover={{ bg: "brand.50" }}
              >
                <Icon as={FaFilter} mr={2} />
                {showFiltro ? "Ocultar Filtro" : "Filtrar"}
              </Button>
            </HStack>

            <HStack gap={3}>
              <Button colorScheme="brand" _hover={{ bg: "brand.600" }}>
                <Icon as={FaUpload} mr={2} /> Importar
              </Button>
              <Button colorScheme="brand" _hover={{ bg: "brand.600" }}>
                <Icon as={FaPrint} mr={2} /> Imprimir
              </Button>
              <Button colorScheme="brand" _hover={{ bg: "brand.600" }}>
                <Icon as={FaDownload} mr={2} /> Exportar CSV
              </Button>
            </HStack>
          </HStack>

          {/* ===== Campo de Busca ===== */}
          <HStack gap={2} mb={4} maxW="400px">
            <Icon as={FaSearch} color="gray.300" />
            <Input
              placeholder="Pesquisar por nome..."
              bg="gray.50"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              _placeholder={{ color: "gray.400" }}
            />
          </HStack>

          {/* ===== Filtro Avançado (opcional) ===== */}
          {showFiltro && (
            <Box bg="white" p={4} mb={4} borderRadius="md" boxShadow="sm">
              <HStack gap={3} wrap="wrap">
                <Input
                  placeholder="Filtrar por CPF"
                  bg="gray.50"
                  size="sm"
                  maxW="200px"
                />
                <Input
                  placeholder="Filtrar por Empresa"
                  bg="gray.50"
                  size="sm"
                  maxW="250px"
                />
                {/* coloque outros filtros adicionais aqui */}
                <Button colorScheme="brand" size="sm">
                  Aplicar Filtro
                </Button>
              </HStack>
            </Box>
          )}

          {/* ===== Tabela com estilo “zebra stripes” ===== */}
          <Box overflowX="auto" bg="white" borderRadius="md" boxShadow="base">
            <chakra.table width="100%">
              <chakra.thead bg="gray.800">
                <chakra.tr>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    <chakra.input
                      type="checkbox"
                      checked={
                        selecionados.length === visitantes.length &&
                        visitantes.length > 0
                      }
                      onChange={toggleSelecionarTodos}
                    />
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    ID
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="left"
                    color="white"
                    fontSize="sm"
                  >
                    Nome
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    CPF
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    RG
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="left"
                    color="white"
                    fontSize="sm"
                  >
                    Empresa Visitante
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="left"
                    color="white"
                    fontSize="sm"
                  >
                    Empresa a Visitar
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    Validade
                  </chakra.th>
                  <chakra.th
                    px={4}
                    py={3}
                    textAlign="center"
                    color="white"
                    fontSize="sm"
                  >
                    Ações
                  </chakra.th>
                </chakra.tr>
              </chakra.thead>

              <chakra.tbody>
                {visitantesFiltrados.map((v) => (
                  <chakra.tr key={v.id} _odd={{ bg: "gray.50" }}>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                    >
                      <chakra.input
                        type="checkbox"
                        checked={selecionados.includes(v.id)}
                        onChange={() => toggleSelecionado(v.id)}
                      />
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {v.id}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="left"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {v.nome}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {v.cpf || "-"}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {v.rg || "-"}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="left"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {v.visitorCompany || "-"}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="left"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {v.visitedCompanyName || "-"}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                      color="gray.700"
                    >
                      {v.shelfLifeDate} {v.shelfLifeTime}
                    </chakra.td>
                    <chakra.td
                      px={4}
                      py={2}
                      textAlign="center"
                      fontSize="sm"
                    >
                      <HStack justify="center" gap={2}>
                        <Button
                          size="xs"
                          colorScheme="blue"
                          onClick={() => navigate(`/edit-visitor/${v.id}`)}
                          _hover={{ bg: "blue.600" }}
                        >
                          <Icon as={FaEdit} mr={1} /> Editar
                        </Button>
                        <Button
                          size="xs"
                          colorScheme="red"
                          onClick={() => removerPessoa(v.user_id)}
                          _hover={{ bg: "red.600" }}
                        >
                          <Icon as={FaTrash} mr={1} /> Excluir
                        </Button>
                      </HStack>
                    </chakra.td>
                  </chakra.tr>
                ))}
              </chakra.tbody>
            </chakra.table>
          </Box>
        </Box>
      </Box>
    </SidebarLayout>
  );
}
