import {
  Box, Heading, Input, Text, SimpleGrid, CardBody, Button, HStack,
  CardRoot
} from '@chakra-ui/react';
import { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { useToast } from '@chakra-ui/toast';


export default function DashboardPessoasPage() {
  type Pessoa = {
    id: number;
    nome: string;
    matricula: string;
    email: string;
    telefone: string;
    fotoUrl?: string;
  };

  const [pessoas, setPessoas] = useState<Pessoa[]>([]);
  const [filtro, setFiltro] = useState('');
  const navigate = useNavigate();
  const toast = useToast();

  useEffect(() => {
    carregarPessoas();
  }, []);

  const carregarPessoas = async () => {
    try {
      const res = await axios.get('http://localhost:3000/pessoas');
      setPessoas(res.data);
    } catch {
      setPessoas([]);
    }
  };

  const deletarPessoa = async (id: number) => {
    try {
      await axios.delete(`http://localhost:3000/pessoas/${id}`);
      setPessoas(prev => prev.filter(p => p.id !== id));
      toast({ title: 'Pessoa deletada com sucesso.', status: 'success', duration: 3000, isClosable: true });
    } catch (e) {
      toast({ title: 'Erro ao deletar pessoa.', status: 'error', duration: 3000, isClosable: true });
    }
  };

  const pessoasFiltradas = pessoas.filter((p: any) =>
    p.nome.toLowerCase().includes(filtro.toLowerCase())
  );

  return (
    <Box p={6}>
      <HStack justify="space-between" mb={4}>
        <Heading size="lg">Pessoas Cadastradas</Heading>
        <Button colorScheme="green" onClick={() => navigate('/cadastropessoa')}>
          Cadastrar Nova Pessoa
        </Button>
      </HStack>

      <Input
        placeholder="Buscar por nome..."
        mb={4}
        value={filtro}
        onChange={(e) => setFiltro(e.target.value)}
      />

      <SimpleGrid columns={[1, 2, 3]} letterSpacing={4}>
        {pessoasFiltradas.map((p: Pessoa) => (
          <CardRoot key={p.id} borderWidth={1} borderRadius="md" boxShadow="sm">
            <CardBody>
              {p.fotoUrl && (
                <Box mb={3}>
                  <img
                    src={`http://localhost:3000/${p.fotoUrl}`}
                    alt={`Foto de ${p.nome}`}
                    style={{ width: '100%', borderRadius: '8px' }}
                  />
                </Box>
              )}

              <Text><strong>Nome:</strong> {p.nome}</Text>
              <Text><strong>Matrícula:</strong> {p.matricula}</Text>
              <Text><strong>Email:</strong> {p.email}</Text>
              <Text><strong>Telefone:</strong> {p.telefone}</Text>

              <HStack mt={4}>
                <Button colorScheme="blue" onClick={() => navigate(`/editarpessoa/${p.id}`)}>Editar</Button>
                <Button colorScheme="red" onClick={() => deletarPessoa(p.id)}>Excluir</Button>
              </HStack>
            </CardBody>
          </CardRoot>
        ))}
      </SimpleGrid>
    </Box>
  );
}
