// src/components/ui/SidebarLayout.tsx
import React from "react";
import {
  Box,
  VStack,
  HStack,
  Icon,
  Text,
} from "@chakra-ui/react";
import { useColorModeValue } from "@chakra-ui/color-mode";
import {
  FaTachometerAlt,
  FaUsers,
  FaSitemap,
  FaUserFriends,
  FaCogs,
  FaDoorOpen,
} from "react-icons/fa";
import { useLocation, useNavigate } from "react-router-dom";

interface Props {
  children: React.ReactNode;
}

export default function SidebarLayout({ children }: Props) {
  const navigate = useNavigate();
  const location = useLocation();
  const activeColor = useColorModeValue("brand.500", "brand.300");

  const menuItems = [
    { label: "Dashboard", icon: FaTachometerAlt, path: "/dashboard" },
    { label: "Pessoas", icon: FaUsers, path: "/list-users" },
    { label: "Visitantes", icon: FaUserFriends, path: "/list-visitors" },
    { label: "Departamentos", icon: FaSitemap, path: "/list-departments" },
    // { label: "Empresas", icon: FaBuilding, path: "/list-companies" }, // Ative se houver página de empresas
    // { label: "Quadro de Horários", icon: FaClock, path: "/list-schedules" }, // Ative se implementado
    // { label: "Relatórios", icon: FaFileAlt, path: "/relatorios" }, // Ative se implementado
    { label: "Config. Equipamento", icon: FaCogs, path: "/list-terminals" },
    { label: "Sair", icon: FaDoorOpen, path: "/login" },
  ];

  return (
    <HStack minH="100vh" align="stretch" gap={0}>
      <Box
        w="240px"
        bg="dark.soft"
        p={4}
        color="white"
        borderRight="1px solid"
        borderColor="gray.700"
      >
        <VStack align="start" gap={1}>
          {menuItems.map((item) => (
            <HStack
              key={item.path}
              w="full"
              px={3}
              py={2}
              borderRadius="md"
              cursor="pointer"
              bg={
                location.pathname === item.path
                  ? "whiteAlpha.200"
                  : "transparent"
              }
              _hover={{ bg: "whiteAlpha.100" }}
              onClick={() => navigate(item.path)}
            >
              <Icon as={item.icon} color={activeColor} />
              <Text fontWeight="medium">{item.label}</Text>
            </HStack>
          ))}
        </VStack>
      </Box>

      <Box flex="1" bg="gray.50" _dark={{ bg: "gray.900" }} p={4}>
        {children}
      </Box>
    </HStack>
  );
}
