// src/pages/departments/EditDepartmentPage.tsx
import { useState, useEffect } from 'react';
import {
  Box,
  Heading,
  HStack,
  VStack,
  Text,
  chakra,
  Input,
  Button,
  Icon,
  useDisclosure,
  Spinner,
} from '@chakra-ui/react';
import { Select } from '@chakra-ui/select';
import { useColorModeValue } from '@chakra-ui/color-mode'
import { FaArrowCircleLeft, FaSave, FaPlus } from 'react-icons/fa';
import { useNavigate, useParams } from 'react-router-dom';
import axios from 'axios';
import SidebarLayout from '../../components/ui/SidebarLayout';


// Criamos as tags de tabela como componentes Chakra
const Table = chakra('table');
const Thead = chakra('thead');
const Tbody = chakra('tbody');
const Tr = chakra('tr');
const Th = chakra('th');
const Td = chakra('td');

interface Terminal {
  id: number;
  name: string;
  host: string;
}

interface Person {
  id: number;
  nome: string;
  matricula: string;
  rg?: string;
  cpf?: string;
  email?: string;
}

interface Visitor {
  id: number;
  nome: string;
  rg?: string;
  cpf?: string;
  email?: string;
}

export default function EditDepartmentPage() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const { open, onOpen, onClose } = useDisclosure();
  const bg = useColorModeValue('gray.50', 'gray.800');

  // estado formulário
  const [name, setName] = useState('');
  const [terminalId, setTerminalId] = useState<number>(0);
  const [terminals, setTerminals] = useState<Terminal[]>([]);
  // estados de pessoas vinculadas
  const [assignedPeople, setAssignedPeople] = useState<Person[]>([]);
  const [assignedVisitors, setAssignedVisitors] = useState<Visitor[]>([]);
  // para modal de seleção
  const [allPeople, setAllPeople] = useState<Person[]>([]);
  const [allVisitors, setAllVisitors] = useState<Visitor[]>([]);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(false);

  // aba ativa: 'info' | 'pessoas'
  const [activeTab, setActiveTab] = useState<'info' | 'pessoas'>('info');

  // carregar dados iniciais
  useEffect(() => {
    // 1) buscar depto
    axios.get<{ nome: string; terminalId: number; pessoas: Person[]; visitantes: Visitor[] }>(
      `http://localhost:3000/departments/${id}`
    ).then(res => {
      setName(res.data.nome);
      setTerminalId(res.data.terminalId);
      setAssignedPeople(res.data.pessoas || []);
      setAssignedVisitors(res.data.visitantes || []);
    }).catch(() =>
      alert('Erro ao carregar departamento, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco')
    );

    // 2) buscar terminais
    axios.get<Terminal[]>('http://localhost:3000/idface/terminals')
      .then(res => setTerminals(res.data))
      .catch(() =>
        alert('Erro ao carregar terminais, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco')
      );
  }, [id, alert]);

  // salvar alterações
  const handleSave = async () => {
    if (!name.trim()) {
      return alert('Nome é obrigatório, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco');
    }
    try {
      await axios.put(`http://localhost:3000/departments/${id}`, {
        nome: name,
        terminalId,
      });
      // 2) atualizar vínculos
      await axios.put(`http://localhost:3000/departments/${id}`, {
        userIds: [...new Set(Array.from(selectedIds)
          .filter(k => k.startsWith('person:'))
          .map(k => Number(k.split(':')[1])))],
        visitorIds: [...new Set(Array.from(selectedIds)
          .filter(k => k.startsWith('visitor:'))
          .map(k => Number(k.split(':')[1])))],
      });


      alert({ title: 'Departamento atualizado!', status: 'success', isClosable: true });
      navigate('/list-departments');
    } catch (err: any) {
      alert('Erro ao atualizar, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco');
    }
  };

  // abrir modal e buscar todas pessoas/visitantes
  const openAssignModal = async () => {
    setLoading(true);
    try {
      const [pRes, vRes] = await Promise.all([
        axios.get<Person[]>('http://localhost:3000/pessoas'),
        axios.get<Visitor[]>('http://localhost:3000/visitors'),
      ]);
      setAllPeople(pRes.data);
      setAllVisitors(vRes.data);
      onOpen();
    } finally {
      setLoading(false);
    }
  };

  // marcar/desmarcar seleção
  const toggleSelect = (kind: 'person' | 'visitor', pid: number) => {
    const key = `${kind}:${pid}`;
    setSelectedIds(prev => {
      const s = new Set(prev);
      s.has(key) ? s.delete(key) : s.add(key);
      return s;
    });
  };

  const loadAssignedData = async () => {
    setLoading(true);
    try {
      const [pessoasRes, visitantesRes] = await Promise.all([
        axios.get<Person[]>('http://localhost:3000/pessoas'),
        axios.get<Visitor[]>('http://localhost:3000/visitors'),
      ]);
      setAllPeople(pessoasRes.data);
      setAllVisitors(visitantesRes.data);
    } catch (e: any) {
      alert('Erro ao buscar pessoas e visitantes, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco');
    } finally {
      setLoading(false);
    }
  };

  const handleTabChange = (tab: 'info' | 'pessoas') => {
    setActiveTab(tab);
    if (tab === 'pessoas') {
      loadAssignedData();
    }
  };

  return (
    <SidebarLayout>
      <Box bg={bg} minH="100vh" p={6}>
        {/* header */}
        <HStack mb={4} gap={2}>
          <Icon as={FaArrowCircleLeft} boxSize={6} />
          <Button variant="ghost" size="sm" onClick={() => navigate('/list-departments')}>
            Cancelar
          </Button>
          <Heading size="lg">Editar Departamento</Heading>
        </HStack>

        {/* abas manuais */}
        <HStack borderBottom="1px solid" borderColor="gray.200" mb={4}>
          <Button flex={1} variant={activeTab === 'info' ? 'solid' : 'ghost'} onClick={() => handleTabChange('info')}>
            Informações Gerais
          </Button>
          <Button flex={1} variant={activeTab === 'pessoas' ? 'solid' : 'ghost'} onClick={() => handleTabChange('pessoas')}>
            Pessoas
          </Button>
        </HStack>

        {/* conteúdo aba Info */}
        {activeTab === 'info' && (
          <VStack gap={4} align="stretch">
            <Box>
              <Text>Nome <chakra.span color="red.500">*</chakra.span></Text>
              <Input
                placeholder="Nome do departamento"
                bg="gray.50"
                value={name}
                onChange={e => setName(e.target.value)}
              />
            </Box>
            <Box>
              <Text>Terminal iDFace</Text>
              <Select
                placeholder="Selecione"
                bg="gray.50"
                value={terminalId || ''}
                onChange={e => setTerminalId(Number(e.target.value))}
              >
                {terminals.map(t => (
                  <option key={t.id} value={t.id}>
                    {t.name} ({t.host})
                  </option>
                ))}
              </Select>
            </Box>
          </VStack>
        )}

        {/* conteúdo aba Pessoas */}
        {activeTab === 'pessoas' && (
          <>
            <HStack justify="space-between" mb={2}>
              <Text fontWeight="bold">Pessoas vinculadas</Text>
              <Button size="sm" onClick={openAssignModal}>
                <Icon as={FaPlus} />
                Adicionar
              </Button>
            </HStack>
            <Table w="full">
              <Thead>
                <Tr><Th>Nome</Th><Th>Matrícula</Th></Tr>
              </Thead>
              <Tbody>
                {(assignedPeople.length + assignedVisitors.length) ? (
                  <>
                    {assignedPeople.map(p => (
                      <Tr key={`p${p.id}`}><Td>{p.nome}</Td><Td>{p.matricula}</Td></Tr>
                    ))}
                    {assignedVisitors.map(v => (
                      <Tr key={`v${v.id}`}><Td>{v.nome}</Td><Td>—</Td></Tr>
                    ))}
                  </>
                ) : (
                  <Tr><Td colSpan={2}>Nenhum registro</Td></Tr>
                )}
              </Tbody>
            </Table>
          </>
        )}

        {/* botões Salvar/Cancelar */}
        <HStack justify="flex-end" mt={6}>
          <Button variant="outline" onClick={() => navigate('/list-departments')}>
            Cancelar
          </Button>
          <Button colorScheme="brand" onClick={handleSave}>
            <Icon as={FaSave} />
            Salvar
          </Button>
        </HStack>

        {/* Dialog de vinculação */}
        {open && (
          <Box
            position="fixed"
            top="0"
            left="0"
            w="100vw"
            h="100vh"
            bg="blackAlpha.600"
            display="flex"
            alignItems="center"
            justifyContent="center"
            zIndex="9999"
          >
            <Box
              bg="white"
              maxW="90vw"
              w="6xl"
              p={6}
              borderRadius="md"
              boxShadow="xl"
              overflowY="auto"
              maxH="90vh"
            >
              <HStack justify="space-between" mb={4}>
                <Heading size="md">Adicionar Pessoas/Visitantes</Heading>
                <Button size="sm" variant="ghost" onClick={onClose}>X</Button>
              </HStack>

              {loading ? (
                <Spinner />
              ) : (
                <VStack gap={4} align="stretch">
                  <Text fontWeight="bold">Pessoas</Text>
                  <Table w="full" align='center'>
                    <Thead>
                      <Tr>
                      </Tr>
                    </Thead>
                    <Tbody alignContent={'center'}>
                      {allPeople.map(p => (
                        <Tr key={p.id} alignContent={'flex-end'}>
                          <Td align='center'>
                            <input
                              type="checkbox"
                              checked={selectedIds.has(`person:${p.id}`)}
                              onChange={() => toggleSelect('person', p.id)}
                            />
                          </Td>
                          <Td align='center'>{p.nome}</Td>
                        </Tr>
                      ))}
                    </Tbody>
                  </Table>

                  <Text fontWeight="bold" mt={4}>Visitantes</Text>
                  <Table w="full">
                    <Thead>
                      <Tr>
                      </Tr>
                    </Thead>
                    <Tbody>
                      {allVisitors.map(v => (
                        <Tr key={v.id}>
                          <Td>
                            <input
                              type="checkbox"
                              checked={selectedIds.has(`visitor:${v.id}`)}
                              onChange={() => toggleSelect('visitor', v.id)}
                            />
                          </Td>
                          <Td>{v.nome}</Td>
                        </Tr>
                      ))}
                    </Tbody>
                  </Table>

                  <HStack justify="flex-end" mt={6}>
                    <Button onClick={onClose}>Cancelar</Button>
                    <Button colorScheme="brand" onClick={onClose}>Adicionar</Button>
                  </HStack>
                </VStack>
              )}
            </Box>
          </Box>
        )}
      </Box>
    </SidebarLayout>
  );
}
