import {
  Box,
  Button,
  Input,
  VStack,
  Heading,
  Image,
} from '@chakra-ui/react';
import { useToast } from '@chakra-ui/toast';
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

export default function LoginPage() {
  const [username, setUsername] = useState('admin');
  const [password, setPassword] = useState('admin');
  const navigate = useNavigate();
  const toast = useToast();

  const handleLogin = async () => {
    try {
      await axios.post('http://localhost:3000/users', {
        nome: username,
        senha: password,
        isMaster: false,
      });

      toast({ title: 'Login realizado com sucesso!', status: 'success' });
      navigate('/dashboard');
    } catch (err: any) {
      toast({
        title: 'Erro no login',
        description: err?.response?.data?.message || 'Erro desconhecido',
        status: 'error',
      });
    }
  };

  return (
    <Box
      minH="100vh"
      bg="dark.soft"
      display="flex"
      alignItems="center"
      justifyContent="center"
      px={4}
    >
      <Box
        bg="white"
        borderRadius="xl"
        boxShadow="2xl"
        p={8}
        maxW="lg"
        w="full"
      >
        <VStack letterSpacing={5}>
          <Image
            src="http://localhost:3000/uploads/logoTechtra.png"
            alt="Logo Techtra"
            maxW="160px"
            mx="auto"
          />
          <Heading size="lg" color="brand.500">
            Login
          </Heading>

          <Input
            placeholder="Usuário"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            size="lg"
            bg="gray.100"
          />
          <Input
            placeholder="Senha"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            size="lg"
            bg="gray.100"
          />

          <Button
            colorScheme="brand"
            w="full"
            size="lg"
            onClick={handleLogin}
          >
            Entrar
          </Button>

          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate('/registro-inicial')}
            w="full"
            color="brand.500"
          >
            Criar conta
          </Button>

          <Button
            fontVariationSettings="link"
            size="sm"
            color="gray.500"
            onClick={() => alert('Recuperação de senha ainda não implementada.')}
          >
            Esqueci minha senha
          </Button>
        </VStack>
      </Box>
    </Box>
  );
}
