// src/pages/CadastrarPessoaPage.tsx
import {
    Box,
    Button,
    FieldRoot,
    Input,
    VStack,
    Heading,
    Image,
} from '@chakra-ui/react';
import { useEffect, useRef, useState } from 'react';
import { useToast } from '@chakra-ui/toast';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

export default function CadastrarPessoaPage() {
    const navigate = useNavigate();
    const toast = useToast();
    const [form, setForm] = useState({
        nome: '',
        matricula: '',
        cpf: '',
        email: '',
        telefone: '',
        senha: '',
    });
    const [loading, setLoading] = useState(false);
    const [capturedImage, setCapturedImage] = useState<string | null>(null);
    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        navigator.mediaDevices.getUserMedia({ video: true })
            .then((stream) => {
                if (videoRef.current) {
                    videoRef.current.srcObject = stream;
                }
            })
            .catch(() => toast({ title: 'Erro ao acessar a câmera', status: 'error' }));
    }, []);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        setForm({ ...form, [name]: value });
    };

    const handleCapture = () => {
        if (videoRef.current && canvasRef.current) {
            const context = canvasRef.current.getContext('2d');
            if (context) {
                context.drawImage(videoRef.current, 0, 0, 300, 300);
                const imageData = canvasRef.current.toDataURL('image/jpeg');
                setCapturedImage(imageData);
            }
        }
    };

    const handleSubmit = async () => {
        if (!capturedImage) {
            toast({ title: 'Capture uma foto!', status: 'warning' });
            return;
        }

        const blob = await (await fetch(capturedImage)).blob();
        const fotoFile = new File([blob], 'foto.jpg', { type: 'image/jpeg' });

        const formData = new FormData();
        Object.entries(form).forEach(([key, value]) => formData.append(key, value));
        formData.append('foto', fotoFile);

        try {
            setLoading(true);
            await axios.post('http://localhost:3000/pessoas/enviar-idface', formData);
            toast({ title: 'Pessoa cadastrada com sucesso.', status: 'success' });
            navigate('/pessoas');
        } catch (error: any) {
            toast({
                title: 'Erro ao enviar',
                description: error?.response?.data?.message || 'Erro desconhecido',
                status: 'error',
            });
        } finally {
            setLoading(false);
        }
    };

    return (
        <Box maxW="6xl" mx="auto" mt={10} p={6}>
            <Heading size="lg" mb={6}>Cadastro de Pessoa</Heading>
            <VStack letterSpacing={4} align="stretch" mb={10}>
                {Object.entries(form).map(([field, value]) => (
                    <div key={field}>
                        <FieldRoot>{field[0].toUpperCase() + field.slice(1)}</FieldRoot>
                        <Input name={field} value={value} onChange={handleChange} />
                    </div>
                ))}

                <FieldRoot>Captura de Foto</FieldRoot>
                <video ref={videoRef} width="300" height="300" autoPlay muted />
                <canvas ref={canvasRef} width="300" height="300" style={{ display: 'none' }} />
                {capturedImage && <Image src={capturedImage} alt="Preview" maxH="200px" />}
                <Button onClick={handleCapture}>Capturar Foto</Button>
                <Button colorScheme="blue" loading={loading} onClick={handleSubmit}>Enviar para iDFace</Button>
            </VStack>
        </Box>
    );
}
