// src/pages/visitors/EditVisitorPage.tsx
import React, { useEffect, useRef, useState } from "react";
import {
  Box,
  Heading,
  HStack,
  VStack,
  Input,
  Button,
  Image,
  Text,
  Icon,
  chakra,
  Spinner,
} from "@chakra-ui/react";
import { Select } from "@chakra-ui/select";
import { useToast } from "@chakra-ui/toast";
import { useColorModeValue } from "@chakra-ui/color-mode";
import { FaCamera, FaArrowCircleLeft, FaSave, FaBuilding } from "react-icons/fa";
import { useNavigate, useParams } from "react-router-dom";
import axios from "axios";
import SidebarLayout from "../../components/ui/SidebarLayout";

const API_URL = import.meta.env.VITE_API_URL || "http://localhost:3000";

type TabKey = "geral" | "recursos";
const TABS: { key: TabKey; label: React.ReactNode }[] = [
  { key: "geral", label: "Geral" },
  { key: "recursos", label: <><FaBuilding /> Empresa/Grupos</> },
];

interface Terminal { id: number; name: string; host: string; }
interface Group { id: number; nome: string; }
interface Company { id: number; nome: string; }
interface Department { id: number; nome: string; terminal: Terminal; }

interface VisitorForm {
  pessoaId?: number;
  nome: string;
  documentType: "0" | "1";
  idUsuario: string;
  rg: string;
  cpf: string;
  visitorCompany: string;
  comments: string;
  phone: string;
  email: string;
  shelfLifeDate: string;
  shelfLifeTime: string;
  departmentId: number;
  terminalId: number;
  selectedGroups: number[];
  visitedCompanyId?: number;
}

const INITIAL_FORM: VisitorForm = {
  nome: "",
  documentType: "0",
  idUsuario: "",
  rg: "",
  cpf: "",
  visitorCompany: "",
  comments: "",
  phone: "",
  email: "",
  shelfLifeDate: "",
  shelfLifeTime: "",
  departmentId: 0,
  terminalId: 0,
  selectedGroups: [],
  visitedCompanyId: undefined,
};

export default function EditVisitorPage() {
  const { id } = useParams<{ id: string }>();
  const toast = useToast();
  const navigate = useNavigate();
  const bg = useColorModeValue("gray.50", "gray.800");

  const [form, setForm] = useState<VisitorForm>({ ...INITIAL_FORM });
  const [departments, setDepartments] = useState<Department[]>([]);
  const [groups, setGroups] = useState<Group[]>([]);
  const [companies, setCompanies] = useState<Company[]>([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [photoVisitor, setPhotoVisitor] = useState<File | null>(null);
  const [previewVisitor, setPreviewVisitor] = useState<string | null>(null);
  const [showCam, setShowCam] = useState(false);
  const [activeTab, setActiveTab] = useState<TabKey>("geral");
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // 1) Carrega departamentos
  useEffect(() => {
    axios.get<Department[]>(`${API_URL}/departments`)
      .then(res => setDepartments(res.data))
      .catch(() => toast({ title: "Erro ao carregar departamentos", status: "error", isClosable: true }));
  }, [toast]);

  // 2) Carrega empresas e inicializa shelf-life
  useEffect(() => {
    axios.get<Company[]>(`${API_URL}/group?type=2`)
      .then(res => setCompanies(res.data))
      .catch(() => console.warn("Erro ao carregar empresas"));

    const now = new Date();
    setForm(f => ({
      ...f,
      shelfLifeDate: now.toISOString().slice(0, 10),
      shelfLifeTime: now.toISOString().slice(11, 16),
    }));
  }, []);

  // 3) Quando departamento muda, define terminal e grupos
  useEffect(() => {
    if (!form.departmentId) return;
    const dep = departments.find(d => d.id === form.departmentId);
    if (dep) {
      setForm(f => ({ ...f, terminalId: dep.terminal.id, selectedGroups: [] }));
      axios.get<Group[]>(`${API_URL}/departments/${form.departmentId}/groups`)
        .then(res => {
          if (!res.data.length) {
            axios.post(`${API_URL}/groups`, {
              nome: `Grupo ${dep.nome}`,
              descricao: `Padrão ${dep.nome}`,
              departmentId: form.departmentId,
              type: 3,
            }).then(() =>
              axios.get<Group[]>(`${API_URL}/departments/${form.departmentId}/groups`)
                .then(r => setGroups(r.data))
            );
          } else {
            setGroups(res.data);
          }
        })
        .catch(() => toast({ title: "Erro ao carregar/criar grupos", status: "error", isClosable: true }));
    }
  }, [form.departmentId, departments, toast]);

  // 4) Carrega dados do visitante
  useEffect(() => {
    setLoading(true);
    axios.get(`${API_URL}/visitors/${id}`)
      .then(res => {
        const data: any = res.data;
        setForm({
          pessoaId: data.pessoaId,
          nome: data.nome,
          documentType: data.documentType,
          idUsuario: data.idUsuario,
          rg: data.rg,
          cpf: data.cpf,
          visitorCompany: data.visitorCompany,
          comments: data.comments,
          phone: data.phone,
          email: data.email,
          shelfLifeDate: data.shelfLifeDate.slice(0, 10),
          shelfLifeTime: data.shelfLifeTime,
          departmentId: data.departmentId,
          terminalId: data.terminalId,
          selectedGroups: data.selectedGroups || [],
          visitedCompanyId: data.visitedCompanyId,
        });
        if (data.fotoVisitorUrl) setPreviewVisitor(data.fotoVisitorUrl);
      })
      .catch(() => {
        toast({ title: "Erro ao carregar visitante", status: "error", isClosable: true });
        navigate("/list-visitors");
      })
      .finally(() => setLoading(false));
  }, [id, toast, navigate]);

  // handlers genéricos
  const handleField = <K extends keyof VisitorForm>(field: K, value: VisitorForm[K]) => {
    setForm(f => ({ ...f, [field]: value }));
  };

  const handleMulti = (opts: HTMLCollectionOf<HTMLOptionElement>) => {
    const vals = Array.from(opts).map(o => Number(o.value));
    setForm(f => ({ ...f, selectedGroups: vals }));
  };

  // foto visitante
  const uploadVisitorPhoto = (file: File | null) => {
    setPhotoVisitor(file);
    if (file) setPreviewVisitor(URL.createObjectURL(file));
  };

  const openCamera = async () => {
    setShowCam(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch {
      toast({ title: "Erro ao acessar câmera", status: "error", isClosable: true });
      setShowCam(false);
    }
  };

  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current) return;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    canvas.toBlob(blob => {
      if (blob) {
        const file = new File([blob], "foto.jpg", { type: "image/jpeg" });
        setPhotoVisitor(file);
        setPreviewVisitor(URL.createObjectURL(file));
      }
    }, "image/jpeg", 0.9);
    (video.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    setShowCam(false);
  };

  // submit
  const onSubmit = async () => {
    if (!form.nome.trim()) { toast({ title: "Nome obrigatório", status: "warning", isClosable: true }); return; }
    if (form.documentType === "1" && !form.cpf.trim()) { toast({ title: "CPF obrigatório", status: "warning", isClosable: true }); return; }
    if (!form.departmentId) { toast({ title: "Selecione um departamento", status: "warning", isClosable: true }); return; }
    setSubmitting(true);
    try {
      if (photoVisitor) {
        const fd = new FormData(); fd.append("foto", photoVisitor);
        const res = await axios.post(`${API_URL}/idface/user_test_image/${form.terminalId}`, fd, {
          headers: { 'Content-Type': 'application/octet-stream' }
        });
        if (!res.data?.success) throw new Error("Imagem não aceita pelo iDFace");
      }
      const { data: pessoaId } = await axios.put<number>(`${API_URL}/visitors/${id}`, {
        nome: form.nome,
        matricula: form.idUsuario,
        idUsuario: form.idUsuario,
        rg: form.rg,
        cpf: form.cpf,
        email: form.email,
        telefone: form.phone,
        observacoes: form.comments,
        departmentId: form.departmentId,
        terminalId: form.terminalId,
        userIdIdface: form.pessoaId,
        grupos: form.selectedGroups,
        administrador: false,
        inativo: false,
        listaExcecao: false,
      });
      if (photoVisitor) {
        const fd2 = new FormData(); fd2.append("foto", photoVisitor); fd2.append("user_id", String(pessoaId));
        await axios.put(`${API_URL}/idface/foto/${form.terminalId}`, fd2, { headers: { "Content-Type": "multipart/form-data" } });
      }
      await axios.put(`${API_URL}/visitors/${id}`, form);
      toast({ title: "Visitante atualizado!", status: "success", isClosable: true });
      navigate("/list-visitors");
    } catch (err: any) {
      toast({ title: "Erro na atualização", description: err.response?.data?.message || err.message, status: "error", isClosable: true });
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <SidebarLayout>
        <Box bg={bg} minH="100vh" p={6} display="flex" alignItems="center" justifyContent="center">
          <Spinner size="xl" />
        </Box>
      </SidebarLayout>
    );
  }

  return (
    <SidebarLayout>
      <Box bg={bg} minH="100vh" p={6}>
        <Box maxW="900px" mx="auto">
          <HStack mb={4} gap={2}>
            <Icon as={FaArrowCircleLeft} />
            <Button variant="ghost" size="sm" onClick={() => navigate("/list-visitors")}>Voltar</Button>
            <Heading>Editar Visitante</Heading>
          </HStack>
          <HStack align="flex-start" gap={4}>
            {/* Foto visitante */}
            <VStack w="260px" bg="white" p={4} rounded="md" shadow="sm">
              <Box rounded="full" overflow="hidden" boxSize="150px" bg="gray.100">
                <Image src={previewVisitor || `${API_URL}/uploads/profile_user.jpg`} alt="Visitor" boxSize="150px" objectFit="cover" />
              </Box>
              <Input type="file" accept="image/*" size="sm" onChange={e => uploadVisitorPhoto(e.target.files?.[0] || null)} />
              <Button size="sm" variant="outline" onClick={openCamera}>
                <Icon as={FaCamera} mr={2} /> Tirar Foto
              </Button>
              {showCam && <>
                <video ref={videoRef} autoPlay style={{ width: '100%', borderRadius: 8 }} />
                <Button size="sm" onClick={capturePhoto}>Capturar</Button>
                <canvas ref={canvasRef} style={{ display: 'none' }} />
              </>}
              <Text fontWeight="bold">Foto Visitante</Text>
              <Box h={2} w="full" bg="gray.200" my={4} />
            </VStack>
            {/* Form & Tabs */}
            <Box flex={1} bg="white" p={6} rounded="md" shadow="sm">
              <HStack borderBottom="1px solid" borderColor="gray.200" mb={4}>
                {TABS.map(tab => (
                  <Button
                    key={tab.key}
                    flex={1}
                    variant={activeTab === tab.key ? "solid" : "ghost"}
                    colorScheme={activeTab === tab.key ? "brand" : "gray"}
                    onClick={() => setActiveTab(tab.key)}
                  >
                    {tab.label}
                  </Button>
                ))}
              </HStack>
              {activeTab === "geral" && (
                <VStack align="stretch" gap={4}>
                  <Box>
                    <Text fontSize="sm">Nome <chakra.span color="red.500">*</chakra.span></Text>
                    <Input placeholder="Nome" value={form.nome} onChange={e => handleField("nome", e.target.value)} />
                  </Box>
                  <Box>
                    <Text fontSize="sm">Departamento</Text>
                    <Select
                      placeholder="Selecione depto."
                      value={form.departmentId || ""}
                      onChange={e => handleField("departmentId", Number(e.target.value))}
                    >
                      {departments.map(d => <option key={d.id} value={d.id}>{d.nome}</option>)}
                    </Select>
                  </Box>
                  <Box>
                    <Text fontSize="sm">Tipo Documento</Text>
                    <Select
                      value={form.documentType}
                      onChange={e => handleField("documentType", e.target.value as any)}
                    >
                      <option value="0">RG</option>
                      <option value="1">CPF</option>
                    </Select>
                  </Box>
                  {form.documentType === "0" ? (
                    <Input placeholder="RG" value={form.rg} onChange={e => handleField("rg", e.target.value)} />
                  ) : (
                    <Input placeholder="CPF" value={form.cpf} onChange={e => handleField("cpf", e.target.value)} />
                  )}
                  <Input placeholder="ID Usuário" value={form.idUsuario} onChange={e => handleField("idUsuario", e.target.value)} />
                  <Input placeholder="Empresa Visitante" value={form.visitorCompany} onChange={e => handleField("visitorCompany", e.target.value)} />
                  <Input placeholder="Observações" value={form.comments} onChange={e => handleField("comments", e.target.value)} />
                  <Input placeholder="Telefone" value={form.phone} onChange={e => handleField("phone", e.target.value)} />
                  <Input type="email" placeholder="E-mail" value={form.email} onChange={e => handleField("email", e.target.value)} />
                  <HStack gap={2}>
                    <Input type="date" value={form.shelfLifeDate} onChange={e => handleField("shelfLifeDate", e.target.value)} />
                    <Input type="time" value={form.shelfLifeTime} onChange={e => handleField("shelfLifeTime", e.target.value)} />
                  </HStack>
                </VStack>
              )}
              {activeTab === "recursos" && (
                <VStack align="stretch" gap={4}>
                  <Box>
                    <Text fontSize="sm">Grupos</Text>
                    <Select
                      multiple
                      size={Math.min(groups.length, 5).toString()}
                      value={form.selectedGroups.map(String)}
                      onChange={e => handleMulti(e.target.selectedOptions)}
                    >
                      {groups.map(g => <option key={g.id} value={g.id}>{g.nome}</option>)}
                    </Select>
                  </Box>
                  <Box>
                    <Text fontSize="sm">Empresa a Visitar</Text>
                    <Select
                      placeholder="Nenhuma"
                      value={form.visitedCompanyId || ""}
                      onChange={e => handleField("visitedCompanyId", Number(e.target.value))}
                    >
                      {companies.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                    </Select>
                  </Box>
                </VStack>
              )}
              <HStack justify="flex-end" pt={6} gap={3}>
                <Button variant="outline" onClick={() => navigate("/list-visitors")}>Cancelar</Button>
                <Button colorScheme="brand" onClick={onSubmit} loading={submitting}>
                  <Icon as={FaSave} mr={2} />Salvar
                </Button>
              </HStack>
            </Box>
          </HStack>
        </Box>
      </Box>
    </SidebarLayout>
  );
}
