// src/pages/EquipamentoIDFacePage.tsx

import {
    Box,
    Button,
    Heading,
    Input,
    VStack,
    Center,
    Badge,
    FieldRoot,
    FieldLabel,
} from '@chakra-ui/react';
import { useToast } from '@chakra-ui/toast';
import { useState } from 'react';
import axios from 'axios';

export default function EquipamentoIDFacePage() {
    const toast = useToast();

    const [nome, setNome] = useState('');
    const [ip, setIp] = useState('');
    const [porta, setPorta] = useState('');
    const [token, setToken] = useState('');
    const [status, setStatus] = useState<'offline' | 'online' | 'pendente' | null>(null);
    const [loadingStatus, setLoadingStatus] = useState(false);
    const [loadingCadastro, setLoadingCadastro] = useState(false);

    const handleCadastrar = async () => {
        setLoadingCadastro(true);
        try {
            const res = await axios.post('http://localhost:3000/equipamentos/idface', {
                nome,
                ip,
                porta,
                token,
            });

            toast({
                title: 'Equipamento cadastrado com sucesso.',
                description: res.data?.mensagem || '',
                status: 'success',
                duration: 3000,
                isClosable: true,
            });
        } catch (error: any) {
            toast({
                title: 'Erro ao cadastrar equipamento',
                description: error?.response?.data?.message || 'Erro desconhecido',
                status: 'error',
                duration: 5000,
                isClosable: true,
            });
        } finally {
            setLoadingCadastro(false);
        }
    };

    const handleTestarStatus = async () => {
        setLoadingStatus(true);
        setStatus(null);
        try {
            const res = await axios.get('http://localhost:3000/equipamentos/idface/status', {
                params: { ip, porta },
            });

            setStatus(res.data?.online ? 'online' : 'offline');
        } catch (error) {
            setStatus('offline');
        } finally {
            setLoadingStatus(false);
        }
    };

    const renderStatusBadge = () => {
        if (!status) return null;
        return (
            <Badge
                colorScheme={status === 'online' ? 'green' : 'red'}
                variant="subtle"
                mt={2}
                px={4}
                py={1}
                borderRadius="full"
                fontSize="md"
            >
                {status === 'online' ? 'Equipamento Online' : 'Equipamento Offline'}
            </Badge>
        );
    };

    return (
        <Box maxW="xl" mx="auto" mt={10} p={6} borderWidth={1} borderRadius="lg" boxShadow="lg">
            <Heading size="lg" mb={6} textAlign="center" color="blue.500">
                Configuração do iDFace
            </Heading>

            <VStack letterSpacing={4} align="stretch">
                <form aria-required>
                    <FieldRoot>
                        <FieldLabel>Nome do Equipamento</FieldLabel>
                        <Input placeholder="Ex: Portaria Principal" value={nome} onChange={(e) => setNome(e.target.value)} />
                    </FieldRoot>
                </form>

                <form aria-required>
                    <FieldRoot>
                        <FieldLabel>IP do iDFace</FieldLabel>
                        <Input placeholder="Ex: 192.168.0.100" value={ip} onChange={(e) => setIp(e.target.value)} />
                    </FieldRoot>
                </form>

                <form aria-required>
                    <FieldRoot>
                        <FieldLabel>Porta</FieldLabel>
                        <Input placeholder="Ex: 8080" value={porta} onChange={(e) => setPorta(e.target.value)} />
                    </FieldRoot>
                </form>

                <form aria-required>
                    <FieldRoot>
                        <FieldLabel>Token de Acesso</FieldLabel>
                        <Input type="password" value={token} onChange={(e) => setToken(e.target.value)} />
                    </FieldRoot>
                </form>

                <div />

                <Button
                    colorScheme="green"
                    onClick={handleCadastrar}
                    loading={loadingCadastro}
                    loadingText="Cadastrando"
                >
                    Cadastrar Equipamento
                </Button>

                <Button
                    variant="outline"
                    colorScheme="blue"
                    onClick={handleTestarStatus}
                    loading={loadingStatus}
                    loadingText="Testando"
                >
                    Testar Conexão
                </Button>

                <Center>{renderStatusBadge()}</Center>
            </VStack>
        </Box>
    );
}
