// src/pages/users/AddUserPage.tsx
import React, { useEffect, useRef, useState } from "react";
import {
  Box,
  Heading,
  HStack,
  VStack,
  Input,
  Button,
  Image,
  Text,
  Icon,
  chakra,
} from "@chakra-ui/react";
import { Select } from '@chakra-ui/select';
import { useColorModeValue } from '@chakra-ui/color-mode'
import {
  FaCamera,
  FaArrowCircleLeft,
  FaSave,
  FaFingerprint,
  FaCreditCard,
  FaQrcode,
  FaBuilding,
  FaInfoCircle,
} from "react-icons/fa";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import SidebarLayout from "../../components/ui/SidebarLayout";

interface Department {
  id: number;
  nome: string;
  terminal: {
    id: number;
    name: string;
    host: string;
  };
}

interface UserForm {
  nome: string;
  matricula: string;
  idUsuario: string;
  rg: string;
  cpf: string;
  email: string;
  telefone: string;
  senha: string;
  confirmarSenha: string;
  observacoes: string;
  departmentId: number;
  terminalId: number;
  administrador: boolean;
  inativo: boolean;
  listaExcecao: boolean;
  userIdIdface: number;
}

const INITIAL_FORM: UserForm = {
  nome: "",
  matricula: "",
  idUsuario: "",
  rg: "",
  cpf: "",
  email: "",
  telefone: "",
  senha: "",
  confirmarSenha: "",
  observacoes: "",
  departmentId: 0,
  terminalId: 0,
  administrador: false,
  inativo: false,
  listaExcecao: false,
  userIdIdface: 0
};

const TABS = [
  { key: "geral", label: "Geral" },
  { key: "digitais", label: <><FaFingerprint /> Digitais</> },
  { key: "cartoes", label: <><FaCreditCard /> Cartões</> },
  { key: "qrcode", label: <><FaQrcode /> QR Code</> },
  { key: "deptos", label: <><FaBuilding /> Deptos./Grupos</> },
  { key: "info", label: <><FaInfoCircle /> Info</> },
] as const;

type TabKey = typeof TABS[number]["key"];

export default function AddUserPage() {
  const navigate = useNavigate();
  const bg = useColorModeValue("gray.50", "gray.800");

  const [form, setForm] = useState<UserForm>({ ...INITIAL_FORM });
  const [foto, setFoto] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [showCamera, setShowCamera] = useState(false);
  const [activeTab, setActiveTab] = useState<TabKey>("geral");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [departments, setDepartments] = useState<Department[]>([]);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // carrega departamentos
  useEffect(() => {
    axios.get<Department[]>("http://localhost:3000/departments")
      .then(res => setDepartments(res.data))
      .catch(() =>
        alert("Erro ao carregar departamentos, verifique se os departamentos estão cadastrados"
        ));
  }, [alert]);

  // handleChange genérico
  const handleChange = <K extends keyof UserForm>(field: K, value: string | boolean) => {
    setForm(prev => {
      const next = { ...prev, [field]: value } as UserForm;
      if (field === "departmentId") {
        const dep = departments.find(d => d.id === Number(value));
        next.terminalId = dep?.terminal.id || 0;
      }
      return next;
    });
  };

  // upload foto
  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    setFoto(file);
    if (file) setPreview(URL.createObjectURL(file));
  };

  // câmera
  const openCamera = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch {
      alert("Erro ao acessar câmera! Verifique se o seu computador está com a camera ativada e devidamente liberada no navegador!");
      setShowCamera(false);
    }
  };
  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current) return;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      alert("Sistema indisponível, entre em contato com o Suporte técnico");
      return;
    }
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    canvas.toBlob(blob => {
      if (blob) {
        const file = new File([blob], "foto.jpg", { type: "image/jpeg" });
        setFoto(file);
        setPreview(URL.createObjectURL(file));
      }
    }, "image/jpeg", 0.9);
    (video.srcObject as MediaStream).getTracks().forEach(track => track.stop());
    setShowCamera(false);
  };

  // salvar
  const handleSubmit = async () => {
    if (!form.departmentId) {
      alert("Selecione um departamento.");
      return;
    }
    if (form.senha !== form.confirmarSenha) {
      alert("Senhas não coincidem.");
      return;
    }
    setIsSubmitting(true);
    try {
      // 1) Valida a imagem no iDFace, se houver
      if (foto) {
        const fd = new FormData();
        fd.append("foto", foto);

        const response = await axios.post(
          `http://localhost:3000/idface/user_test_image/${form.terminalId}`,
          fd,
          { headers: { 'Content-Type': 'application/octet-stream' } }
        );

        if (response.data?.success != true) {
          console.log(JSON.stringify(response))

          throw new Error("A imagem não foi aceita pelo terminal iDFace.");
        }
      }

      // 2) Envia o formulário para criar a pessoa
      const pessoaResp = await axios.post("http://localhost:3000/pessoas", form);
      const pessoaId = pessoaResp.data;

      // 3) Envia a foto ao iDFace
      if (foto) {
        const fd = new FormData();
        fd.append("foto", foto);
        fd.append("user_id", String(pessoaId));

      }

      // 4) Cria o usuário após sucesso do iDFace
      await axios.post("http://localhost:3000/users", {
        nome: form.nome,
        pessoaId,
        userIdIdface: form.userIdIdface,
        senha: form.senha,
        administrador: form.administrador,
        inativo: form.inativo,
        listaExcecao: form.listaExcecao,
      });

      alert("Usuário criado!");
      navigate("/list-users");

    } catch (err: any) {
      alert(JSON.stringify("Erro ao cadastrar."
      ));
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <SidebarLayout>
      <Box bg={bg} minH="100vh" p={6}>
        <Box maxW="900px" mx="auto">
          {/* Cabeçalho */}
          <HStack mb={6} gap={2}>
            <Icon as={FaArrowCircleLeft} boxSize={6} color="gray.500" />
            <Button variant="ghost" onClick={() => navigate("/list-users")}>Voltar</Button>
            <Heading size="lg">Nova Pessoa</Heading>
          </HStack>

          <HStack align="flex-start" gap={4}>
            {/* Foto & Câmera */}
            <VStack w="260px" bg="white" p={4} rounded="md" shadow="sm">
              <Box rounded="full" overflow="hidden" boxSize="150px" bg="gray.100">
                <Image
                  src={preview || "http://localhost:3000/uploads/profile_user.jpg"}
                  alt="Preview"
                  boxSize="150px"
                  objectFit="cover"
                />
              </Box>
              <Input type="file" accept="image/*" onChange={handleFotoUpload} size="sm" />
              <Button size="sm" variant="outline" onClick={openCamera}>
                <Icon as={FaCamera} mr={2} /> Tirar Foto
              </Button>
              {showCamera && (
                <VStack>
                  <video ref={videoRef} autoPlay style={{ width: '100%', borderRadius: 8 }} />
                  <Button size="sm" onClick={capturePhoto}>Capturar</Button>
                  <canvas ref={canvasRef} style={{ display: 'none' }} />
                </VStack>
              )}
            </VStack>

            {/* Formulário */}
            <Box flex={1} bg="white" p={6} rounded="md" shadow="sm">
              {/* Abas */}
              <HStack borderBottom="1px solid" borderColor="gray.200" mb={4}>
                {TABS.map(tab => (
                  <Button
                    key={tab.key}
                    flex={1}
                    variant={activeTab === tab.key ? "solid" : "ghost"}
                    colorScheme={activeTab === tab.key ? "brand" : "gray"}
                    onClick={() => setActiveTab(tab.key as TabKey)}
                  >
                    {tab.label}
                  </Button>
                ))}
              </HStack>

              {/* Aba “Geral” */}
              {activeTab === "geral" && (
                <VStack align="stretch" gap={4}>
                  <Input
                    placeholder="Nome*"
                    value={form.nome}
                    onChange={e => handleChange("nome", e.target.value)}
                  />
                  <Input
                    placeholder="Matrícula"
                    value={form.matricula}
                    onChange={e => handleChange("matricula", e.target.value)}
                  />
                  <Input
                    maxLength={12}
                    placeholder="ID Usuário"
                    value={form.idUsuario}
                    onChange={e => handleChange("idUsuario", e.target.value)}
                  />
                  <Input
                    placeholder="RG"
                    value={form.rg}
                    onChange={e => handleChange("rg", e.target.value)}
                  />
                  <Input
                    placeholder="CPF"
                    value={form.cpf}
                    onChange={e => handleChange("cpf", e.target.value)}
                  />
                  <Input
                    type="email"
                    placeholder="E-mail"
                    value={form.email}
                    onChange={e => handleChange("email", e.target.value)}
                  />
                  <Input
                    placeholder="Telefone"
                    value={form.telefone}
                    onChange={e => handleChange("telefone", e.target.value)}
                  />
                  <Input
                    type="password"
                    placeholder="Senha*"
                    value={form.senha}
                    onChange={e => handleChange("senha", e.target.value)}
                  />
                  <Input
                    type="password"
                    placeholder="Confirmar senha"
                    value={form.confirmarSenha}
                    onChange={e => handleChange("confirmarSenha", e.target.value)}
                  />
                  <Input
                    placeholder="Observações"
                    value={form.observacoes}
                    onChange={e => handleChange("observacoes", e.target.value)}
                  />
                  <HStack gap={6}>
                    <HStack>
                      <chakra.input type="checkbox" checked={form.administrador} onChange={(e) => handleChange("administrador", e.target.checked)} />
                      <Text>Administrador</Text>
                    </HStack>
                    <HStack>
                      <chakra.input type="checkbox" checked={form.inativo} onChange={(e) => handleChange("inativo", e.target.checked)} />
                      <Text>Inativo</Text>
                    </HStack>
                    <HStack>
                      <chakra.input type="checkbox" checked={form.listaExcecao} onChange={(e) => handleChange("listaExcecao", e.target.checked)} />
                      <Text>Lista Exceção</Text>
                    </HStack>
                  </HStack>
                </VStack>
              )}
              {/* Aba “Deptos./Grupos” */}
              {activeTab === "deptos" && (
                <VStack align="stretch" gap={4}>
                  <Text fontSize="sm">
                    Departamento <chakra.span color="red.500">*</chakra.span>
                  </Text>
                  <Select
                    placeholder="Selecione um departamento"
                    value={form.departmentId || ""}
                    onChange={e => handleChange("departmentId", e.target.value)}
                  >
                    {departments.map(d => (
                      <option key={d.id} value={d.id}>
                        {d.nome} — {d.terminal.name}
                      </option>
                    ))}
                  </Select>
                </VStack>
              )}

              {/* Abas em desenvolvimento */}
              {activeTab !== "geral" && activeTab !== "deptos" && (
                <VStack align="center" py={10} gap={4}>
                  <Icon
                    as={{
                      digitais: FaFingerprint,
                      cartoes: FaCreditCard,
                      qrcode: FaQrcode,
                      info: FaInfoCircle,
                    }[activeTab]}
                    boxSize={8}
                    color="gray.400"
                  />
                  <Text color="gray.500">Funcionalidade em desenvolvimento</Text>
                </VStack>
              )}

              {/* Botões Salvar / Cancelar */}
              <HStack justify="flex-end" pt={6}>
                <Button variant="outline" onClick={() => navigate("/list-users")}>
                  Cancelar
                </Button>
                <Button
                  colorScheme="brand"
                  onClick={handleSubmit}
                  loading={isSubmitting}
                >
                  <Icon as={FaSave} mr={2} />
                  Salvar
                </Button>
              </HStack>
            </Box>
          </HStack>
        </Box>
      </Box>
    </SidebarLayout>
  );
}
