// src/pages/terminals/IDFaceConfigPage.tsx
import React, { useEffect, useState } from "react";
import {
  Box,
  Heading,
  VStack,
  HStack,
  Input,
  Button,
  Text,
  Icon,
} from "@chakra-ui/react";
import { FaArrowCircleLeft, FaSave, FaPlug } from "react-icons/fa";
import { useNavigate, useParams } from "react-router-dom";
import axios from "axios";
import SidebarLayout from "../../components/ui/SidebarLayout";
import { useToast } from "@chakra-ui/toast";

type IDFaceConfig = {
  baseUrl: string;
  deviceId: number;
};

export default function IDFaceConfigPage() {
  const navigate = useNavigate();
  const toast = useToast();
  const { id } = useParams<{ id: string }>();
  const [config, setConfig] = useState<IDFaceConfig>({
    baseUrl: "",
    deviceId: 0,
  });
  const [loadingConfig, setLoadingConfig] = useState(false);
  const [testing, setTesting] = useState(false);

  useEffect(() => {
    if (!id) return;
    setLoadingConfig(true);
    axios
      .get<IDFaceConfig>(`http://localhost:3000/idface/${id}`)
      .then((res) => setConfig(res.data))
      .catch(() => {
        // Pode não haver config ainda
      })
      .finally(() => setLoadingConfig(false));
  }, [id]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setConfig((prev) => ({
      ...prev,
      [name]: name === "deviceId" ? Number(value) : value,
    }));
  };

  const handleSave = async () => {
    if (!config.baseUrl.trim() || !config.deviceId) {
      toast({
        title: "Base URL e Device ID são obrigatórios",
        status: "warning",
        isClosable: true,
      });
      return;
    }
    try {
      await axios.post("http://localhost:3000/idface/config", config);
      toast({
        title: "Configuração do iDFace salva com sucesso",
        status: "success",
        isClosable: true,
      });
    } catch {
      toast({
        title: "Erro ao salvar configuração",
        status: "error",
        isClosable: true,
      });
    }
  };

  const handleTestConnection = async () => {
    setTesting(true);
    try {
      // 1) força login
      await axios.post("http://localhost:3000/idface/login");
      // 2) valida sessão
      const resp = await axios.get<{ valid: boolean }>(
        "http://localhost:3000/idface/session/valid"
      );
      if (resp.data.valid) {
        toast({
          title: "Conexão OK!",
          description: "Sessão validada com sucesso no iDFace.",
          status: "success",
          isClosable: true,
        });
      } else {
        throw new Error("Sessão inválida");
      }
    } catch (err) {
      toast({
        title: "Falha na conexão",
        description:
          err instanceof Error ? err.message : "Não foi possível conectar",
        status: "error",
        isClosable: true,
      });
    } finally {
      // 3) encerra sessão
      try {
        await axios.post("http://localhost:3000/idface/logout");
      } catch {}
      setTesting(false);
    }
  };

  return (
    <SidebarLayout>
      <Box bg="dark.soft" minH="100vh" px={6} py={8}>
        <Box maxW="600px" mx="auto">
          <HStack mb={4} gap={2}>
            <Icon as={FaArrowCircleLeft} color="white" />
            <Button
              colorScheme="gray"
              size="sm"
              onClick={() => navigate("/list-terminals")}
            >
              Voltar
            </Button>
            <Heading size="lg" color="brand.500">
              Configuração iDFace
            </Heading>
          </HStack>

          <Box bg="white" borderRadius="md" boxShadow="md" p={6}>
            <VStack align="stretch" gap={4}>
              <Box>
                <Text fontSize="sm" mb={1}>
                  Base URL do iDFace{" "}
                  <Text as="span" color="red.500">
                    *
                  </Text>
                </Text>
                <Input
                  name="baseUrl"
                  placeholder="http://192.168.1.11"
                  value={config.baseUrl}
                  onChange={handleChange}
                  bg="gray.50"
                  disabled={loadingConfig}
                />
              </Box>

              <Box>
                <Text fontSize="sm" mb={1}>
                  Device ID{" "}
                  <Text as="span" color="red.500">
                    *
                  </Text>
                </Text>
                <Input
                  name="deviceId"
                  type="number"
                  placeholder="1"
                  value={config.deviceId}
                  onChange={handleChange}
                  bg="gray.50"
                  disabled={loadingConfig}
                />
              </Box>

              <HStack justify="flex-end" gap={3} pt={4}>
                <Button
                  size="sm"
                  colorScheme="gray"
                  onClick={() => navigate("/list-terminals")}
                >
                  <FaArrowCircleLeft /> Cancelar
                </Button>
                <Button
                  size="sm"
                  colorScheme="brand"
                  onClick={handleSave}
                  loading={loadingConfig}
                >
                  <FaSave /> Salvar
                </Button>
                <Button
                  size="sm"
                  colorScheme="teal"
                  onClick={handleTestConnection}
                  loading={testing}
                >
                  <FaPlug /> Testar Conexão
                </Button>
              </HStack>
            </VStack>
          </Box>
        </Box>
      </Box>
    </SidebarLayout>
  );
}
