// src/pages/terminals/DownloadUsersPage.tsx
import { useEffect, useState } from "react";
import {
  Box,
  Heading,
  HStack,
  Button,
  Icon,
  chakra,
  Text
} from "@chakra-ui/react";
import { useToast } from "@chakra-ui/toast";
import { FaDownload, FaUndo } from "react-icons/fa";
import axios from "axios";
import { useNavigate, useParams } from "react-router-dom";
import SidebarLayout from "../../components/ui/SidebarLayout";

type TerminalUser = {
  id: number;
  nome: string;
  matricula: string;
  rg: string;
  cpf: string;
  email: string;
};

export default function DownloadUsersPage() {
  const { id } = useParams<{ id: string }>();
  const toast = useToast();
  const navigate = useNavigate();
  const [users, setUsers] = useState<TerminalUser[]>([]);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    axios
      .get<TerminalUser[]>(`http://localhost:3000/idface/${id}/users`)
      .then((res) => setUsers(res.data))
      .catch(() =>
        toast({
          title: "Erro ao carregar usuários do terminal",
          status: "error",
          isClosable: true,
        })
      )
      .finally(() => setLoading(false));
  }, [id, toast]);

  const handleDownload = () => {
    axios
      .post(`http://localhost:3000/idface/${id}/download-users`)
      .then(() => {
        toast({
          title: "Download iniciado com sucesso",
          status: "success",
          isClosable: true,
        });
      })
      .catch(() =>
        toast({
          title: "Erro ao iniciar download",
          status: "error",
          isClosable: true,
        })
      );
  };

  return (
    <SidebarLayout>
      <Box bg="dark.soft" minH="100vh" px={6} py={8}>
        <Box maxW="1000px" mx="auto">
          <Heading size="lg" mb={4} color="brand.500">
            Usuários do Terminal #{id}
          </Heading>

          <HStack mb={4} gap={3}>
            <Button
              colorScheme="gray"
              size="sm"
              onClick={() => navigate(`/list-terminals`)}
            >
              <Icon as={FaUndo} mr={2} /> Voltar
            </Button>
            <Button
              colorScheme="brand"
              onClick={handleDownload}
              as={FaDownload}
            >
              Baixar Usuários
            </Button>
          </HStack>

          {loading ? (
            <Text>Carregando …</Text>
          ) : users.length === 0 ? (
            <Text>Nenhum usuário encontrado no terminal.</Text>
          ) : (
            <Box overflowX="auto" bg="white" borderRadius="md" boxShadow="base">
              <chakra.table width="100%">
                <chakra.thead bg="gray.100">
                  <chakra.tr>
                    <chakra.th px={3} py={2} textAlign="center" fontSize="sm">
                      ID
                    </chakra.th>
                    <chakra.th px={3} py={2} textAlign="left" fontSize="sm">
                      Nome
                    </chakra.th>
                    <chakra.th px={3} py={2} textAlign="center" fontSize="sm">
                      Matrícula
                    </chakra.th>
                    <chakra.th px={3} py={2} textAlign="center" fontSize="sm">
                      RG
                    </chakra.th>
                    <chakra.th px={3} py={2} textAlign="center" fontSize="sm">
                      CPF
                    </chakra.th>
                    <chakra.th px={3} py={2} textAlign="center" fontSize="sm">
                      E-mail
                    </chakra.th>
                  </chakra.tr>
                </chakra.thead>
                <chakra.tbody>
                  {users.map((u, _idx) => (
                    <chakra.tr key={u.id} _odd={{ bg: "gray.50" }}>
                      <chakra.td
                        px={3}
                        py={2}
                        textAlign="center"
                        fontSize="sm"
                        color="gray.700"
                      >
                        {u.id}
                      </chakra.td>
                      <chakra.td
                        px={3}
                        py={2}
                        textAlign="left"
                        fontSize="sm"
                        color="gray.700"
                      >
                        {u.nome}
                      </chakra.td>
                      <chakra.td
                        px={3}
                        py={2}
                        textAlign="center"
                        fontSize="sm"
                        color="gray.700"
                      >
                        {u.matricula}
                      </chakra.td>
                      <chakra.td
                        px={3}
                        py={2}
                        textAlign="center"
                        fontSize="sm"
                        color="gray.700"
                      >
                        {u.rg}
                      </chakra.td>
                      <chakra.td
                        px={3}
                        py={2}
                        textAlign="center"
                        fontSize="sm"
                        color="gray.700"
                      >
                        {u.cpf}
                      </chakra.td>
                      <chakra.td
                        px={3}
                        py={2}
                        textAlign="center"
                        fontSize="sm"
                        color="gray.700"
                      >
                        {u.email}
                      </chakra.td>
                    </chakra.tr>
                  ))}
                </chakra.tbody>
              </chakra.table>
            </Box>
          )}
        </Box>
      </Box>
    </SidebarLayout>
  );
}
