// src/pages/dashboard/DashboardPage.tsx
import {
  Box,
  Grid,
  GridItem,
  Icon,
  Heading,
  StatValueText,
} from '@chakra-ui/react';
import { Stat, StatLabel } from '@chakra-ui/react';
import { useEffect, useState } from 'react';
import { useColorModeValue } from '@chakra-ui/color-mode';
import axios from 'axios';
import SidebarLayout from '../../components/ui/SidebarLayout';
import { FaIdCard, FaSmile, FaClock, FaLock, FaEye, FaNetworkWired, FaFingerprint, FaUsers } from 'react-icons/fa';

export default function DashboardPage() {
  const [data, setData] = useState<any>({});

  useEffect(() => {
    axios.get('http://localhost:3000/util')
      .then(res => setData(res.data))
      .catch(() => setData({}));
  }, []);

  const cardBg = useColorModeValue('white', 'gray.800');
  const iconColor = 'brand.500';

  const cards = [
    { label: 'Pessoas Ativas', value: `${data.userActiveCount || 0} / ${data.userCount || 0}`, icon: FaUsers },
    { label: 'Visitantes Ativos', value: `${data.visitorActiveCount || 0} / ${data.visitorCount || 0}`, icon: FaSmile },
    { label: 'Digitais Ativas', value: `${data.templateActiveCount || 0} / ${data.templateCount || 0}`, icon: FaFingerprint },
    { label: 'Cartões Cadastrados', value: data.cardCount || 0, icon: FaIdCard },
    { label: 'Faces Registradas', value: data.faceCount || 0, icon: FaSmile },
    { label: 'Contingência', value: data.contingenceCount || 0, icon: FaClock },
    { label: 'Regras de Acesso', value: data.accessRulesCount || 0, icon: FaLock },
    { label: 'Acessos Recentes', value: data.logCount || 0, icon: FaEye },
    { label: 'Departamentos', value: data.departmentCount || 0, icon: FaNetworkWired },
    { label: 'Terminais Ativos', value: data.terminalCount || 0, icon: FaNetworkWired },
  ];

  return (
    <SidebarLayout>
      <Box px={8} py={10}>
        <Heading mb={6} color="brand.500">Painel de Controle</Heading>
        <Grid templateColumns={['1fr', 'repeat(2, 1fr)', 'repeat(4, 1fr)']} gap={6}>
          {cards.map((card, idx) => (
            <GridItem key={idx} bg={cardBg} p={5} rounded="xl" shadow="md">
              <Stat.Root>
                <Icon as={card.icon} boxSize={6} color={iconColor} mb={2} />
                <StatLabel>{card.label}</StatLabel>
                <StatValueText>{card.value}</StatValueText>
              </Stat.Root>
            </GridItem>
          ))}
        </Grid>
      </Box>
    </SidebarLayout>
  );
}
