// src/pages/users/AddGroupsPage.tsx
import {
  Box,
  Heading,
  HStack,
  VStack,
  Button,
  Icon,
  Text,
  chakra,
  Spinner,
} from "@chakra-ui/react";
import { FaArrowCircleLeft, FaSave } from "react-icons/fa";
import { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import axios from "axios";
import SidebarLayout from "../../components/ui/SidebarLayout";

type Grupo = {
  id: number;
  nome: string;
  selecionado?: boolean;
};

export default function AddGroupsPage() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>(); // id do usuário
  const [loading, setLoading] = useState(true);
  const [todosGrupos, setTodosGrupos] = useState<Grupo[]>([]);
  const [gruposAssociados, setGruposAssociados] = useState<number[]>([]);

  // Carrega lista de todos os grupos e quais já estão associados ao usuário
  useEffect(() => {
    if (!id) return;
    Promise.all([
      axios.get<Grupo[]>("http://localhost:3000/grupos"), // rota de todos grupos
      axios.get<number[]>(`http://localhost:3000/pessoas/${id}/grupos`), // rota de grupos associados
    ])
      .then(([resGrupos, resAssociados]) => {
        const associados = resAssociados.data;
        const lista: Grupo[] = resGrupos.data.map((g) => ({
          ...g,
          selecionado: associados.includes(g.id),
        }));
        setTodosGrupos(lista);
        setGruposAssociados(associados);
      })
      .catch(() => {
        alert("Erro ao carregar grupos");
        navigate("/list-users");
      })
      .finally(() => setLoading(false));
  }, [id, navigate, alert]);

  if (loading) {
    return (
      <SidebarLayout>
        <Box bg="dark.soft" minH="100vh" px={6} py={8}>
          <Spinner size="xl" color="brand.500" />
        </Box>
      </SidebarLayout>
    );
  }

  // Toggle de seleção de grupo
  const toggleGrupo = (grupoId: number) => {
    setTodosGrupos((prev) =>
      prev.map((g) =>
        g.id === grupoId ? { ...g, selecionado: !g.selecionado } : g
      )
    );
    setGruposAssociados((prev) =>
      prev.includes(grupoId)
        ? prev.filter((gid) => gid !== grupoId)
        : [...prev, grupoId]
    );
  };

  // Submete a associação ao backend
  const handleSalvar = async () => {
    try {
      await axios.post(`http://localhost:3000/pessoas/${id}/grupos`, {
        grupos: gruposAssociados,
      });
      alert("Grupos atualizados com sucesso",
      );
      navigate("/list-users");
    } catch {
      alert("Erro ao salvar grupos",
      );
    }
  };

  return (
    <SidebarLayout>
      <Box bg="dark.soft" minH="100vh" px={6} py={8}>
        <Box maxW="800px" mx="auto">
          <HStack mb={4} gap={2}>
            <Icon as={FaArrowCircleLeft} />
            <Button
              as={FaArrowCircleLeft}
              onClick={() => navigate("/list-users")}
              colorScheme="gray"
              size="sm"
            >
              Voltar
            </Button>
            <Heading size="lg" color="brand.500">
              Vincular Grupos ao Usuário #{id}
            </Heading>
          </HStack>

          <Box bg="white" p={6} borderRadius="md" boxShadow="md">
            <VStack align="stretch" gap={4}>
              {todosGrupos.map((g) => (
                <HStack key={g.id} gap={3}>
                  <chakra.input
                    type="checkbox"
                    checked={g.selecionado || false}
                    onChange={() => toggleGrupo(g.id)}
                  />
                  <Text fontSize="sm">{g.nome}</Text>
                </HStack>
              ))}

              <HStack justify="flex-end" pt={4}>
                <Icon as={FaSave} />
                <Button
                  as={FaSave}
                  colorScheme="brand"
                  onClick={handleSalvar}
                >
                  Salvar
                </Button>
              </HStack>
            </VStack>
          </Box>
        </Box>
      </Box>
    </SidebarLayout>
  );
}
