// src/pages/departments/ListDepartmentsPage.tsx
import {
  Box,
  Button,
  Heading,
  HStack,
  Input,
  Icon,
  chakra,
} from "@chakra-ui/react";
import { FaPlus, FaEdit } from "react-icons/fa";
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import SidebarLayout from "../../components/ui/SidebarLayout";
import axios from "axios";

const API_URL = "http://localhost:3000";

interface Department {
  id: number;
  nome: string;
  descricao: string;
}

export default function ListDepartmentsPage() {
  const navigate = useNavigate();
  const [departments, setDepartments] = useState<Department[]>([]);
  const [search, setSearch] = useState("");

  const loadDepartments = async () => {
    try {
      const res = await axios.get(`${API_URL}/departments`);
      setDepartments(res.data);
    } catch (err) {
      alert('Erro ao carregar departamentos, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco, verifique o cadastro dos mesmos ou entre em contato com o Suporte Técnco');
    }
  };

  useEffect(() => {
    loadDepartments();
  }, []);

  const filteredDepartments = departments.filter((d) =>
    d.nome.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <SidebarLayout>
      <Box bg="dark.soft" minH="100vh" px={6} py={8}>
        <Box maxW="1000px" mx="auto">
          <HStack justify="space-between" mb={6}>
            <Heading size="lg" color="brand.500">Departamentos</Heading>
            <Button colorScheme="brand" onClick={() => navigate("/add-department")}>
              <Icon as={FaPlus} mr={1} />
              Adicionar
            </Button>
          </HStack>

          <HStack mb={4} maxW="400px">
            <Input
              placeholder="Buscar por nome"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              bg="gray.50"
            />
          </HStack>

          <Box bg="white" borderRadius="md" boxShadow="base" overflowX="auto">
            <chakra.table width="100%">
              <chakra.thead bg="gray.800">
                <chakra.tr>
                  <chakra.th px={4} py={3} textAlign="left" color="white" fontSize="sm">ID</chakra.th>
                  <chakra.th px={4} py={3} textAlign="left" color="white" fontSize="sm">Nome</chakra.th>
                  <chakra.th px={4} py={3} textAlign="left" color="white" fontSize="sm">Descrição</chakra.th>
                  <chakra.th px={4} py={3} textAlign="center" color="white" fontSize="sm">Ações</chakra.th>
                </chakra.tr>
              </chakra.thead>
              <chakra.tbody>
                {filteredDepartments.map((dept) => (
                  <chakra.tr key={dept.id} _odd={{ bg: "gray.50" }}>
                    <chakra.td px={4} py={2}>{dept.id}</chakra.td>
                    <chakra.td px={4} py={2}>{dept.nome}</chakra.td>
                    <chakra.td px={4} py={2}>{dept.descricao}</chakra.td>
                    <chakra.td px={4} py={2} textAlign="center">
                      <Button
                        size="xs"
                        colorScheme="blue"
                        onClick={() => navigate(`/edit-department/${dept.id}`)}
                      >
                        <Icon as={FaEdit} mr={1} />
                        Editar
                      </Button>
                    </chakra.td>
                  </chakra.tr>
                ))}
              </chakra.tbody>
            </chakra.table>
          </Box>
        </Box>
      </Box>
    </SidebarLayout>
  );
}
